import React, { useState } from 'react';
import { auth } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup, 
  GoogleAuthProvider 
} from 'firebase/auth';

interface AuthProps {
  onLogin: (name: string, email: string) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      if (isLogin) {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        onLogin(userCredential.user?.displayName || 'User', userCredential.user?.email || '');
      } else {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        onLogin(name || 'New User', userCredential.user?.email || '');
      }
    } catch (err: any) {
      const errorMessage = err.code === 'auth/user-not-found' 
        ? 'No account found with this email.' 
        : err.code === 'auth/wrong-password' 
        ? 'Incorrect password. Please try again.'
        : err.message || 'Authentication failed.';
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const provider = new GoogleAuthProvider();
      const result = await signInWithPopup(auth, provider);
      onLogin(result.user?.displayName || 'Google User', result.user?.email || '');
    } catch (err: any) {
      setError('Google login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-[#0c1a0e] text-slate-100 font-sans selection:bg-primary/30">
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-15%] w-[70%] h-[70%] bg-primary/10 blur-[120px] rounded-full"></div>
