                  setIsEditingCalories(true);
                }
              }}
            >
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-primary transition-colors">Calories</p>
              {isEditingCalories ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
