import React, { useState } from 'react';
import firebase from 'firebase/app';
import 'firebase/auth';
import { auth } from '../services/firebase';

interface AuthProps {
  onLogin: (name: string, email: string) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      if (isLogin) {
        // Fix: Use namespaced signInWithEmailAndPassword from the auth instance.
        const userCredential = await auth.signInWithEmailAndPassword(email, password);
        onLogin(userCredential.user?.displayName || 'User', userCredential.user?.email || '');
      } else {
        // Fix: Use namespaced createUserWithEmailAndPassword from the auth instance.
        const userCredential = await auth.createUserWithEmailAndPassword(email, password);
        onLogin(name || 'New User', userCredential.user?.email || '');
      }
    } catch (err: any) {
      const errorMessage = err.code === 'auth/user-not-found' 
        ? 'No account found with this email.' 
        : err.code === 'auth/wrong-password' 
        ? 'Incorrect password. Please try again.'
        : err.message || 'Authentication failed.';
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      // Fix: Use namespaced GoogleAuthProvider and signInWithPopup from the auth instance.
      const provider = new firebase.auth.GoogleAuthProvider();
      const result = await auth.signInWithPopup(provider);
      onLogin(result.user?.displayName || 'Google User', result.user?.email || '');
    } catch (err: any) {
      setError('Google login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-[#0c1a0e] text-slate-100 font-sans selection:bg-primary/30">
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-15%] w-[70%] h-[70%] bg-primary/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[5%] right-[-10%] w-[60%] h-[60%] bg-primary/5 blur-[100px] rounded-full"></div>
      </div>

      <div className="w-full max-w-[430px] flex flex-col items-center px-8 py-12 relative z-10">
        <div className="w-full text-center mt-8 mb-12">
          <div className="relative inline-block mb-6">
            <div className="absolute -inset-2 bg-primary/20 blur-xl rounded-3xl animate-pulse"></div>
            <div className="relative w-20 h-20 bg-gradient-to-br from-primary/20 to-primary/5 border border-primary/20 rounded-2xl flex items-center justify-center shadow-2xl">
              <span className="material-icons-round text-primary text-5xl">auto_awesome</span>
            </div>
          </div>
          <h1 className="text-4xl font-black tracking-tight text-white mb-2">
            NutriVision <span className="text-primary italic">AI</span>
          </h1>
          <p className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30">
            Intelligent Wellness Hub
          </p>
        </div>

        <div className="w-full bg-white/[0.03] border border-white/5 p-1.5 rounded-2xl mb-8 flex items-center">
          <button 
            onClick={() => setIsLogin(true)}
            className={`flex-1 py-3 text-[11px] font-black uppercase tracking-widest rounded-xl transition-all duration-300 ${isLogin ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Sign In
          </button>
          <button 
            onClick={() => setIsLogin(false)}
            className={`flex-1 py-3 text-[11px] font-black uppercase tracking-widest rounded-xl transition-all duration-300 ${!isLogin ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            New Account
          </button>
        </div>

        <div className="w-full glass-card rounded-[2.5rem] p-8 border border-white/10 shadow-2xl backdrop-blur-2xl">
          {error && (
            <div className="w-full p-4 mb-6 bg-red-500/10 border border-red-500/20 rounded-2xl flex items-center gap-3 animate-in shake duration-300">
              <span className="material-icons-round text-red-400 text-lg">error_outline</span>
              <p className="text-xs font-bold text-red-400 leading-tight">{error}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {!isLogin && (
              <div className="space-y-2">
                <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Full Name</label>
                <div className="relative group">
                  <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors">person</span>
                  <input 
                    required={!isLogin}
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4.5 pl-12 pr-4 text-sm font-medium focus:ring-1 focus:ring-primary/50 focus:border-primary/50 focus:bg-white/[0.06] outline-none transition-all placeholder:text-slate-600" 
                    placeholder="Enter your name" 
                  />
                </div>
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Email Address</label>
              <div className="relative group">
                <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors">alternate_email</span>
                <input 
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4.5 pl-12 pr-4 text-sm font-medium focus:ring-1 focus:ring-primary/50 focus:border-primary/50 focus:bg-white/[0.06] outline-none transition-all placeholder:text-slate-600" 
                  placeholder="name@example.com" 
                  type="email" 
                />
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">Password</label>
                {isLogin && <span className="text-[10px] font-bold text-white/30 hover:text-primary cursor-pointer transition-colors uppercase tracking-widest">Forgot?</span>}
              </div>
              <div className="relative group">
                <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors">lock_open</span>
                <input 
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4.5 pl-12 pr-12 text-sm font-medium focus:ring-1 focus:ring-primary/50 focus:border-primary/50 focus:bg-white/[0.06] outline-none transition-all placeholder:text-slate-600" 
                  placeholder="••••••••" 
                  type="password" 
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={isLoading}
              className="w-full relative bg-primary text-black font-black py-5 rounded-[1.8rem] shadow-[0_8px_30px_rgba(19,236,55,0.3)] hover:brightness-110 active:scale-[0.98] transition-all overflow-hidden flex items-center justify-center uppercase tracking-[0.2em] text-[11px] disabled:opacity-70"
            >
              {isLoading ? (
                <div className="w-5 h-5 border-2 border-black/30 border-t-black rounded-full animate-spin"></div>
              ) : (
                <span>{isLogin ? 'Authenticate' : 'Start Journey'}</span>
              )}
            </button>
          </form>

          <div className="w-full flex items-center my-8 space-x-4">
            <div className="flex-1 h-px bg-white/5"></div>
            <span className="text-white/20 text-[8px] font-black uppercase tracking-[0.4em]">Fast Login</span>
            <div className="flex-1 h-px bg-white/5"></div>
          </div>

          <div className="grid grid-cols-2 gap-4 w-full">
            <button 
              type="button"
              onClick={handleGoogleLogin}
              className="flex items-center justify-center space-x-3 bg-white/[0.03] border border-white/5 py-4 rounded-2xl hover:bg-white/10 transition-all active:scale-95 group"
            >
              <img src="https://www.gstatic.com/images/branding/product/1x/gsa_512dp.png" className="w-5 h-5 grayscale group-hover:grayscale-0 transition-all" alt="Google" />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 group-hover:text-white">Google</span>
            </button>
            <button 
              type="button"
              className="flex items-center justify-center space-x-3 bg-white/[0.03] border border-white/5 py-4 rounded-2xl hover:bg-white/10 transition-all active:scale-95 group"
            >
              <span className="material-icons-round text-slate-400 group-hover:text-white transition-colors">apple</span>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 group-hover:text-white">Apple</span>
            </button>
          </div>
        </div>

        <div className="mt-12 text-center opacity-40">
          <p className="text-[9px] font-bold uppercase tracking-[0.2em] leading-relaxed">
            By continuing, you agree to our <span className="text-white hover:underline cursor-pointer">Terms of Service</span><br/>
            and <span className="text-white hover:underline cursor-pointer">Privacy Policy</span>.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Analytics from './components/Analytics';
import CameraScan from './components/CameraScan';
import Auth from './components/Auth';
import Diary from './components/Diary';
import Profile from './components/Profile';
import FoodGuide from './components/FoodGuide';
import { View, UserProfile, FoodEntry, NutritionData } from './types';
import { auth } from './services/firebase';

const DEFAULT_USER_STATE: UserProfile = {
  name: 'User',
  goal: 'Maintain',
  dailyCalorieGoal: 2200,
  dailyStepGoal: 8000,
  currentSteps: 0,
  weight: 70.0,
  targetWeight: 70.0,
  bmi: 22.0,
  bodyFat: 18.0,
  macros: { protein: 140, carbs: 200, fats: 60, fiber: 30 }
};

export default function App() {
  const [view, setView] = useState<View>('auth');
  const [waterGlasses, setWaterGlasses] = useState(0);
  const [user, setUser] = useState<UserProfile>(DEFAULT_USER_STATE);
  const [entries, setEntries] = useState<FoodEntry[]>([]);

  useEffect(() => {
    // Fix: Used the namespaced onAuthStateChanged listener on the auth instance (v8 style).
    const unsubscribe = auth.onAuthStateChanged((firebaseUser) => {
      if (firebaseUser) {
        const storedProfile = localStorage.getItem(`nv_profile_${firebaseUser.uid}`);
        const storedEntries = localStorage.getItem(`nv_entries_${firebaseUser.uid}`);

        if (storedProfile) {
          setUser(JSON.parse(storedProfile));
        } else {
          const initialProfile = { ...DEFAULT_USER_STATE, name: firebaseUser.displayName || 'New User' };
          setUser(initialProfile);
          localStorage.setItem(`nv_profile_${firebaseUser.uid}`, JSON.stringify(initialProfile));
        }

        if (storedEntries) {
          const parsed = JSON.parse(storedEntries).map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }));
          setEntries(parsed);
        } else {
          setEntries([]);
        }

        setView('home');
      } else {
        setView('auth');
        setUser(DEFAULT_USER_STATE);
        setEntries([]);
      }
    });

    return () => unsubscribe();
  }, []);

  const handleAddEntry = (data: NutritionData & { multiplier?: number }) => {
    const firebaseUser = auth.currentUser;
    if (!firebaseUser) return;

    const newEntry: FoodEntry = {
      id: Date.now().toString(),
      name: data.foodName,
      calories: data.calories,
      protein: data.protein,
      carbs: data.carbs,
      fats: data.fats,
      fiber: data.fiber || 0,
      portionSize: data.portionDescription || '1 serving',
      timestamp: new Date()
    };

    const updatedEntries = [newEntry, ...entries];
    setEntries(updatedEntries);
    localStorage.setItem(`nv_entries_${firebaseUser.uid}`, JSON.stringify(updatedEntries));
    setView('home');
  };

  const handleLogin = (name: string, email: string) => {
    const firebaseUser = auth.currentUser;
    if (firebaseUser) {
      const updatedUser = { ...user, name: name || firebaseUser.displayName || 'User' };
      setUser(updatedUser);
      localStorage.setItem(`nv_profile_${firebaseUser.uid}`, JSON.stringify(updatedUser));
      setView('home');
    }
  };

  const updateUser = (updates: Partial<UserProfile>) => {
    const firebaseUser = auth.currentUser;
    if (!firebaseUser) return;

    const updatedUser = { ...user, ...updates };
    setUser(updatedUser);
    localStorage.setItem(`nv_profile_${firebaseUser.uid}`, JSON.stringify(updatedUser));
  };

  const renderContent = () => {
    switch (view) {
      case 'home': return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
      case 'analytics': return <Analytics user={user} />;
      case 'diary': return <Diary entries={entries} onAddManualEntry={handleAddEntry} />;
      case 'profile': return <Profile user={user} onUpdate={updateUser} />;
      case 'recipes': return <FoodGuide user={user} />;
      case 'camera': return <CameraScan onAddEntry={handleAddEntry} onClose={() => setView('home')} />;
      case 'auth': return <Auth onLogin={handleLogin} />;
      default: return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
    }
  };

  return (
    <Layout activeView={view} onViewChange={setView}>
      {renderContent()}
    </Layout>
  );
}

import React, { useState, useRef } from 'react';
import { UserProfile } from '../types';
import { auth } from '../services/firebase';

interface ProfileProps {
  user: UserProfile;
  onUpdate: (updates: Partial<UserProfile>) => void;
}

const PRESET_AVATARS = [
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Felix',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Aneka',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Tigger',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Spooky',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Buddy',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Cookie',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Milo',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Lilly',
];

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditingCalories, setIsEditingCalories] = useState(false);
  const [isEditingSteps, setIsEditingSteps] = useState(false);
  const [tempCalories, setTempCalories] = useState(user.dailyCalorieGoal);
  const [tempSteps, setTempSteps] = useState(user.dailyStepGoal);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const goals = [
    { id: 'Cut', icon: 'trending_down', label: 'Lose Weight', desc: 'Calorie deficit' },
    { id: 'Maintain', icon: 'trending_flat', label: 'Stay Fit', desc: 'Equal intake' },
    { id: 'Bulk', icon: 'trending_up', label: 'Build Muscle', desc: 'Calorie surplus' },
  ];

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      if (!file.type.startsWith('image/')) {
        setUploadError('Please select a valid image file (PNG, JPG, etc.)');
        return;
      }
      if (file.size > MAX_FILE_SIZE) {
        setUploadError('Image is too large. Please select a file under 5MB.');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ avatarUrl: reader.result as string });
        setIsModalOpen(false);
      };
      reader.onerror = () => {
        setUploadError('Error reading file. Please try again.');
      };
      reader.readAsDataURL(file);
    }
  };

  const selectPreset = (url: string) => {
    setUploadError(null);
    onUpdate({ avatarUrl: url });
    setIsModalOpen(false);
  };

  const generateNewDiceBear = () => {
    setUploadError(null);
    const randomSeed = Math.random().toString(36).substring(7);
    onUpdate({ avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=${randomSeed}` });
    setIsModalOpen(false);
  };

  const handleSaveCalories = () => {
    onUpdate({ dailyCalorieGoal: tempCalories });
    setIsEditingCalories(false);
  };

  const handleSaveSteps = () => {
    onUpdate({ dailyStepGoal: tempSteps });
    setIsEditingSteps(false);
  };

  const openModal = () => {
    setUploadError(null);
    setIsModalOpen(true);
  };

  const handleSignOut = async () => {
    try {
      // Fix: Use the namespaced signOut method on the auth instance (v8 style).
      await auth.signOut();
    } catch (error) {
      console.error("Sign out error:", error);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col items-center text-center">
        <div className="relative group mb-4">
           <div className="absolute -inset-1 bg-gradient-to-tr from-primary to-primary/20 rounded-[2rem] blur opacity-25 group-hover:opacity-50 transition duration-500"></div>
           <div className="relative w-28 h-28 rounded-[2rem] bg-background-dark border-2 border-white/5 p-1 shadow-2xl overflow-hidden">
              <img 
                src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} 
                alt="Profile" 
                className="w-full h-full rounded-[1.8rem] bg-surface-dark object-cover" 
              />
              <button 
                onClick={openModal}
                className="absolute -bottom-2 -right-2 w-10 h-10 bg-primary rounded-2xl flex items-center justify-center text-black shadow-lg border-4 border-background-dark active:scale-90 transition-transform"
              >
                <span className="material-icons-round text-xl">camera_alt</span>
              </button>
           </div>
        </div>
        <h1 className="text-2xl font-black tracking-tight">{user.name}</h1>
        <p className="text-sm text-slate-500 font-medium">Premium Member since Oct 2024</p>
      </header>

      {/* Avatar Customization Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass-card w-full max-sm rounded-[2.5rem] p-6 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden relative">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-black tracking-tight text-white">Choose Avatar</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-white/40 hover:text-white transition-colors">
                <span className="material-icons-round text-lg">close</span>
              </button>
            </div>

            <div className="space-y-6">
              {uploadError && (
                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 animate-in shake duration-300">
                  <span className="material-icons-round text-red-400 text-sm">error_outline</span>
                  <p className="text-[10px] font-bold text-red-400 uppercase tracking-wider">{uploadError}</p>
                </div>
              )}

              <button 
                onClick={() => fileInputRef.current?.click()}
                className={`w-full flex items-center p-4 bg-primary/10 border border-primary/20 rounded-2xl group active:scale-[0.98] transition-all ${uploadError ? 'ring-1 ring-red-500/50' : ''}`}
              >
                <div className="w-10 h-10 rounded-xl bg-primary text-black flex items-center justify-center mr-4">
                  <span className="material-icons-round">upload</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-primary uppercase tracking-wider">Upload Photo</p>
                  <p className="text-[10px] text-slate-500 font-bold">Select from your gallery (Max 5MB)</p>
                </div>
                <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
              </button>

              <div className="space-y-3">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Premium Presets</p>
                <div className="grid grid-cols-4 gap-3">
                  {PRESET_AVATARS.map((url, i) => (
                    <button 
                      key={i} 
                      onClick={() => selectPreset(url)}
                      className={`aspect-square rounded-xl bg-white/5 border-2 transition-all active:scale-90 ${user.avatarUrl === url ? 'border-primary' : 'border-transparent hover:border-white/10'}`}
                    >
                      <img src={url} alt={`Preset ${i}`} className="w-full h-full p-1" />
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={generateNewDiceBear}
                className="w-full flex items-center p-4 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors group"
              >
                <div className="w-10 h-10 rounded-xl bg-white/10 text-white/60 flex items-center justify-center mr-4 group-hover:text-primary transition-colors">
                  <span className="material-icons-round">casino</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-white/80 uppercase tracking-wider">Surprise Me</p>
                  <p className="text-[10px] text-slate-500 font-bold">Generate a random character</p>
                </div>
              </button>
            </div>
          </div>
        </div>
      )}

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Active Goal</h2>
        <div className="grid grid-cols-1 gap-3">
          {goals.map((g) => (
            <button
              key={g.id}
              onClick={() => onUpdate({ goal: g.id as any })}
              className={`flex items-center p-4 rounded-3xl border transition-all ${
                user.goal === g.id 
                  ? 'bg-primary/10 border-primary shadow-[0_0_20px_rgba(19,236,55,0.1)]' 
                  : 'bg-white/5 border-white/5 hover:border-white/10'
              }`}
            >
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 ${user.goal === g.id ? 'bg-primary text-black' : 'bg-white/5 text-slate-500'}`}>
                <span className="material-icons-round text-2xl">{g.icon}</span>
              </div>
              <div className="text-left flex-1">
                <p className={`font-black tracking-tight ${user.goal === g.id ? 'text-primary' : 'text-white'}`}>{g.label}</p>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{g.desc}</p>
              </div>
              {user.goal === g.id && (
                <span className="material-icons-round text-primary">check_circle</span>
              )}
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Daily Targets</h2>
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 space-y-6">
          <div className="flex justify-between items-start">
            <div 
              className="cursor-pointer group" 
              onClick={() => {
                if (!isEditingCalories) {
                  setTempCalories(user.dailyCalorieGoal);
                  setIsEditingCalories(true);
                }
              }}
            >
