export type View = 'home' | 'analytics' | 'diary' | 'recipes' | 'profile' | 'camera';

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Analytics from './components/Analytics';
import CameraScan from './components/CameraScan';
import Diary from './components/Diary';
import Profile from './components/Profile';
import FoodGuide from './components/FoodGuide';
import { View, UserProfile, FoodEntry, NutritionData } from './types';

const STORAGE_KEYS = {
  PROFILE: 'nv_profile_local',
  ENTRIES: 'nv_entries_local',
  WATER: 'nv_water_local'
};

const DEFAULT_USER_STATE: UserProfile = {
  name: 'Fitness Enthusiast',
  goal: 'Maintain',
  dailyCalorieGoal: 2200,
  dailyStepGoal: 8000,
  currentSteps: 0,
  weight: 70.0,
  targetWeight: 70.0,
  bmi: 22.0,
  bodyFat: 18.0,
  macros: { protein: 140, carbs: 200, fats: 60, fiber: 30 }
};

export default function App() {
  const [view, setView] = useState<View>('home');
  const [waterGlasses, setWaterGlasses] = useState(0);
  const [user, setUser] = useState<UserProfile>(DEFAULT_USER_STATE);
  const [entries, setEntries] = useState<FoodEntry[]>([]);

  // Load data on mount
  useEffect(() => {
    const storedProfile = localStorage.getItem(STORAGE_KEYS.PROFILE);
    const storedEntries = localStorage.getItem(STORAGE_KEYS.ENTRIES);
    const storedWater = localStorage.getItem(STORAGE_KEYS.WATER);

    if (storedProfile) {
      setUser(JSON.parse(storedProfile));
    }

    if (storedEntries) {
      const parsed = JSON.parse(storedEntries).map((e: any) => ({
        ...e,
        timestamp: new Date(e.timestamp)
      }));
      setEntries(parsed);
    }

    if (storedWater) {
      setWaterGlasses(parseInt(storedWater, 10) || 0);
    }
  }, []);

  // Persist water glasses
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.WATER, waterGlasses.toString());
  }, [waterGlasses]);

  const handleAddEntry = (data: NutritionData & { multiplier?: number }) => {
    const newEntry: FoodEntry = {
      id: Date.now().toString(),
      name: data.foodName,
      calories: data.calories,
      protein: data.protein,
      carbs: data.carbs,
      fats: data.fats,
      fiber: data.fiber || 0,
      portionSize: data.portionDescription || '1 serving',
      timestamp: new Date()
    };

    const updatedEntries = [newEntry, ...entries];
    setEntries(updatedEntries);
    localStorage.setItem(STORAGE_KEYS.ENTRIES, JSON.stringify(updatedEntries));
    setView('home');
  };

  const updateUser = (updates: Partial<UserProfile>) => {
    const updatedUser = { ...user, ...updates };
    setUser(updatedUser);
    localStorage.setItem(STORAGE_KEYS.PROFILE, JSON.stringify(updatedUser));
  };

  const renderContent = () => {
    switch (view) {
      case 'home': return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
      case 'analytics': return <Analytics user={user} />;
      case 'diary': return <Diary entries={entries} onAddManualEntry={handleAddEntry} />;
      case 'profile': return <Profile user={user} onUpdate={updateUser} />;
      case 'recipes': return <FoodGuide user={user} />;
      case 'camera': return <CameraScan onAddEntry={handleAddEntry} onClose={() => setView('home')} />;
      default: return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
    }
  };

  return (
    <Layout activeView={view} onViewChange={setView}>
      {renderContent()}
    </Layout>
  );
}

