              <button 
                onClick={() => onViewChange('camera')}
                className={`w-14 h-14 rounded-full bg-primary fab-glow flex items-center justify-center shadow-lg active:scale-90 transition-all duration-300 ${activeView === 'camera' ? 'ring-4 ring-primary/20 shadow-primary/40' : ''}`}
              >
                <span className="material-icons-round text-2xl text-black">photo_camera</span>
