                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-white/80 uppercase tracking-wider">Surprise Me</p>
                  <p className="text-[10px] text-slate-500 font-bold">Generate a random character</p>
                </div>
              </button>
            </div>
          </div>
        </div>
      )}

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Active Goal</h2>
        <div className="grid grid-cols-1 gap-3">
          {goals.map((g) => (
            <button
