const DEFAULT_USER_STATE: UserProfile = {
  name: 'Alex Thompson',
  goal: 'Maintain',
  dailyCalorieGoal: 2200,
  dailyStepGoal: 10000,
  dailyWaterGoal: 10,
  currentSteps: 6420,
  weight: 72.5,
  targetWeight: 70.0,
  bmi: 23.4,
  bodyFat: 18.5,
  macros: { protein: 150, carbs: 220, fats: 70, fiber: 30 },
  avatarUrl: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Alex'
};

export default function App() {
  const [view, setView] = useState<View>('home');
  const [waterGlasses, setWaterGlasses] = useState(5);
  const [user, setUser] = useState<UserProfile>(DEFAULT_USER_STATE);
  const [entries, setEntries] = useState<FoodEntry[]>(PLACEHOLDER_ENTRIES);

  // Load data on mount
  useEffect(() => {
    const storedProfile = localStorage.getItem(STORAGE_KEYS.PROFILE);
    const storedEntries = localStorage.getItem(STORAGE_KEYS.ENTRIES);
    const storedWater = localStorage.getItem(STORAGE_KEYS.WATER);

    if (storedProfile) {
      setUser(JSON.parse(storedProfile));
    }

    if (storedEntries) {
      const parsed = JSON.parse(storedEntries).map((e: any) => ({
        ...e,
        timestamp: new Date(e.timestamp)
      }));
      setEntries(parsed);
    }

    if (storedWater) {
      setWaterGlasses(parseInt(storedWater, 10) || 0);
    }
  }, []);

  // Persist water glasses
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.WATER, waterGlasses.toString());
  }, [waterGlasses]);

  const handleAddEntry = (data: NutritionData & { multiplier?: number }) => {
    const newEntry: FoodEntry = {
      id: Date.now().toString(),
      name: data.foodName,
      calories: data.calories,
      protein: data.protein,
      carbs: data.carbs,
      fats: data.fats,
      fiber: data.fiber || 0,
      portionSize: data.portionDescription || '1 serving',
      timestamp: new Date()
    };

    const updatedEntries = [newEntry, ...entries];
    setEntries(updatedEntries);
    localStorage.setItem(STORAGE_KEYS.ENTRIES, JSON.stringify(updatedEntries));
    setView('home');
  };

  const updateUser = (updates: Partial<UserProfile>) => {
    const updatedUser = { ...user, ...updates };
    setUser(updatedUser);
    localStorage.setItem(STORAGE_KEYS.PROFILE, JSON.stringify(updatedUser));
  };

  const renderContent = () => {
    switch (view) {
      case 'home': return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
      case 'analytics': return <Analytics user={user} />;
      case 'diary': return <Diary entries={entries} onAddManualEntry={handleAddEntry} />;
      case 'profile': return <Profile user={user} onUpdate={updateUser} />;
      case 'recipes': return <FoodGuide user={user} />;
      case 'camera': return <CameraScan onAddEntry={handleAddEntry} onClose={() => setView('home')} />;
      default: return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
    }
  };

  return (
    <Layout activeView={view} onViewChange={setView}>
      {renderContent()}
    </Layout>
  );
}

import React, { useMemo } from 'react';
import { FoodEntry, UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  entries: FoodEntry[];
  waterGlasses: number;
  setWaterGlasses: (val: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, entries, waterGlasses, setWaterGlasses }) => {
  const consumed = entries.reduce((acc, entry) => acc + entry.calories, 0);
  const isSurplus = consumed > user.dailyCalorieGoal;
  const isGoalReached = consumed >= user.dailyCalorieGoal * 0.9 && consumed <= user.dailyCalorieGoal;
  const remaining = Math.max(0, user.dailyCalorieGoal - consumed);
  const surplus = isSurplus ? consumed - user.dailyCalorieGoal : 0;

  const progressPercent = Math.min(100, (consumed / user.dailyCalorieGoal) * 100);

  const totalMacros = useMemo(() => entries.reduce((acc, e) => ({
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
    fi: acc.fi + (e.fiber || 0),
  }), { p: 0, c: 0, f: 0, fi: 0 }), [entries]);

  const stepProgress = Math.min(100, (user.currentSteps / user.dailyStepGoal) * 100);
  const waterProgress = Math.min(100, (waterGlasses / (user.dailyWaterGoal || 10)) * 100);

  const getSuggestions = () => {
    const tips = [];
    const proteinDeficit = user.macros.protein - totalMacros.p;
    if (proteinDeficit > 20) {
      tips.push({
        icon: 'egg',
        text: `You need ${Math.round(proteinDeficit)}g more protein. Try a Greek yogurt or some paneer.`,
        color: 'text-primary'
      });
    }
    const fiberDeficit = user.macros.fiber - totalMacros.fi;
    if (fiberDeficit > 10) {
      tips.push({
        icon: 'eco',
        text: `Fiber check: Adding flax seeds or an apple will help digestion today.`,
        color: 'text-green-400'
      });
    }
    if (consumed > user.dailyCalorieGoal * 0.9 && !isSurplus) {
      tips.push({
        icon: 'verified',
        text: `Calorie precision! You are perfectly hitting your target for ${user.goal}.`,
        color: 'text-primary'
      });
    }
    if (waterGlasses < (user.dailyWaterGoal || 10) * 0.5) {
      tips.push({
        icon: 'water_drop',
        text: `Metabolism needs water. Drink more to reach your hydration goal.`,
        color: 'text-blue-400'
      });
    }
    return tips.length > 0 ? tips : [{ icon: 'verified', text: `Spot on! You are executing your plan flawlessly.`, color: 'text-primary' }];
  };

  const suggestions = useMemo(() => getSuggestions(), [totalMacros, consumed, waterGlasses, user]);

  const mainSize = 200;
  const mainCenter = mainSize / 2;
  const mainRadius = 85;
  const mainCircumference = 2 * Math.PI * mainRadius;
  const mainOffset = mainCircumference - (progressPercent / 100) * mainCircumference;

  const MacroCard = ({ label, current, goal, colorClass }: { label: string, current: number, goal: number, colorClass: string }) => {
    const macroPercent = Math.min(100, (current / goal) * 100);
    const smallSize = 64;
    const smallCenter = smallSize / 2;
    const smallRadius = 26;
    const smallCircumference = 2 * Math.PI * smallRadius;
    const smallOffset = smallCircumference - (macroPercent / 100) * smallCircumference;

    return (
      <div className="glass-card rounded-2xl p-4 flex flex-col items-center border border-white/5 shadow-sm transition-all hover:bg-white/[0.05]">
        <div className="relative w-16 h-16 mb-2">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${smallSize} ${smallSize}`}>
            <circle className="text-white/[0.03]" cx={smallCenter} cy={smallCenter} fill="transparent" r={smallRadius} stroke="currentColor" strokeWidth="5" />
            <circle className={colorClass} cx={smallCenter} cy={smallCenter} fill="transparent" r={smallRadius} stroke="currentColor" strokeDasharray={smallCircumference} strokeDashoffset={smallOffset} strokeLinecap="round" strokeWidth="5" style={{ transition: 'stroke-dashoffset 0.5s ease-out' }} />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="text-[10px] font-bold tracking-tighter">{Math.round(macroPercent)}%</span>
          </div>
        </div>
        <p className="text-[11px] font-semibold text-white/80">{label}</p>
        <p className="text-[10px] text-slate-500 font-medium">
          {Math.round(current)}g <span className="opacity-50">/ {goal}g</span>
        </p>
      </div>
    );
  };

  return (
    <div className="space-y-7 pb-10">
      <header className="flex justify-between items-center">
        <div>
          <p className="text-[10px] font-bold text-primary uppercase tracking-[0.2em] mb-1">
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
          </p>
          <h1 className="text-2xl font-black tracking-tight">Hey, {user.name.split(' ')[0]}!</h1>
        </div>
        <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-primary/20 to-primary/5 p-[1px] shadow-lg">
          <div className="w-full h-full rounded-[14px] bg-background-dark overflow-hidden flex items-center justify-center">
            <img src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
      </header>

      <section className="animate-in fade-in slide-in-from-top-4 duration-500">
        <div className="bg-primary/10 border border-primary/20 rounded-2xl p-4 relative overflow-hidden">
          <div className="absolute -right-4 -top-4 opacity-10">
            <span className="material-icons-round text-7xl">psychology</span>
          </div>
          <div className="flex items-start space-x-3">
            <div className={`p-2 rounded-xl bg-background-dark/50 ${suggestions[0].color}`}>
              <span className="material-icons-round text-xl">{suggestions[0].icon}</span>
            </div>
            <div className="flex-1 pr-4">
              <h3 className="text-[10px] font-black uppercase tracking-widest text-primary mb-1">AI Daily Engine</h3>
              <p className="text-sm font-medium leading-relaxed text-white/90 italic">"{suggestions[0].text}"</p>
            </div>
          </div>
        </div>
      </section>

      <section className="glass-card rounded-[2rem] p-8 flex flex-col items-center justify-center relative overflow-hidden border border-white/5 shadow-2xl">
        {isGoalReached && (
          <div className="absolute inset-0 bg-primary/5 animate-pulse pointer-events-none"></div>
        )}
        <div className="relative w-56 h-56 flex items-center justify-center">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${mainSize} ${mainSize}`}>
            <circle className="text-white/5" cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeWidth="14" />
            <circle className={isSurplus ? "text-red-500" : isGoalReached ? "text-primary" : "text-primary/60"} cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeDasharray={mainCircumference} strokeDashoffset={mainOffset} strokeLinecap="round" strokeWidth="14" style={{ transition: 'stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1)', filter: `drop-shadow(0 0 10px ${isSurplus ? 'rgba(239,68,68,0.4)' : 'rgba(19,236,55,0.4)'})` }} />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
            {isSurplus ? (
              <>
                <span className="text-4xl font-black text-red-500 tabular-nums">+{surplus.toLocaleString()}</span>
                <span className="text-[10px] text-red-400 font-bold uppercase tracking-widest mt-1">Surplus kcal</span>
              </>
            ) : (
              <>
                <span className="text-5xl font-black text-white tabular-nums tracking-tighter">{remaining.toLocaleString()}</span>
                <span className="text-[10px] text-white/40 font-bold uppercase tracking-[0.2em] mt-1">kcal left</span>
              </>
            )}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4 w-full mt-10 pt-8 border-t border-white/5">
          <div className="text-center">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1">Logged</p>
            <p className="text-xl font-bold text-white">{consumed.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span></p>
          </div>
          <div className="text-center">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1">Target</p>
            <p className="text-xl font-bold text-white">{user.dailyCalorieGoal.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span></p>
          </div>
        </div>
      </section>

      <section>
        <div className="flex justify-between items-center mb-5 px-1">
          <h2 className="text-[11px] font-black uppercase tracking-[0.25em] text-white/40">Nutrients Today</h2>
          <span className="material-icons-round text-[14px] text-white/40 cursor-pointer">info</span>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <MacroCard label="Protein" current={totalMacros.p} goal={user.macros.protein} colorClass="text-primary" />
          <MacroCard label="Carbs" current={totalMacros.c} goal={user.macros.carbs} colorClass="text-primary/70" />
          <MacroCard label="Fats" current={totalMacros.f} goal={user.macros.fats} colorClass="text-primary/90" />
          <MacroCard label="Fiber" current={totalMacros.fi} goal={user.macros.fiber} colorClass="text-primary/40" />
        </div>
      </section>

      <section className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Step Tracker Card */}
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group">
          <div className="absolute -right-4 -bottom-4 opacity-[0.03] group-hover:scale-110 transition-transform duration-700">
             <span className="material-icons-round text-8xl">directions_run</span>
          </div>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-3">
               <div className="w-10 h-10 bg-primary/20 rounded-2xl flex items-center justify-center"><span className="material-icons-round text-primary text-xl">directions_run</span></div>
               <span className="text-[11px] font-black text-white/30 uppercase tracking-[0.2em]">Steps</span>
            </div>
            {stepProgress >= 100 && <span className="material-icons-round text-primary text-lg">verified</span>}
          </div>
          <div className="flex items-end space-x-2">
            <p className="text-3xl font-black tracking-tight">{user.currentSteps.toLocaleString()}</p>
            <p className="text-sm font-bold text-slate-500 pb-1.5 uppercase tracking-widest">/ {user.dailyStepGoal.toLocaleString()}</p>
          </div>
          <div className="mt-4 w-full h-2 bg-white/5 rounded-full overflow-hidden">
            <div className="h-full bg-primary rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(19,236,55,0.4)]" style={{ width: `${stepProgress}%` }}></div>
          </div>
        </div>

        {/* Hydration Tracker Card */}
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group">
          <div 
            className="absolute inset-0 bg-blue-500/5 transition-all duration-1000 origin-bottom" 
            style={{ transform: `scaleY(${waterProgress / 100})` }}
          />
          <div className="relative z-10">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-3">
                 <div className="w-10 h-10 bg-blue-500/20 rounded-2xl flex items-center justify-center"><span className="material-icons-round text-blue-400 text-xl">water_drop</span></div>
                 <span className="text-[11px] font-black text-white/30 uppercase tracking-[0.2em]">Hydration</span>
              </div>
              <div className="flex space-x-2">
                <button 
                  onClick={() => setWaterGlasses(Math.max(0, waterGlasses - 1))} 
                  className="w-8 h-8 rounded-xl bg-white/5 border border-white/5 flex items-center justify-center text-slate-500 hover:text-white transition-colors"
                >
                  <span className="material-icons-round text-lg">remove</span>
                </button>
                <button 
                  onClick={() => setWaterGlasses(waterGlasses + 1)} 
                  className="w-8 h-8 rounded-xl bg-blue-500/20 border border-blue-500/20 flex items-center justify-center text-blue-400 hover:bg-blue-500/30 transition-all active:scale-90"
                >
                  <span className="material-icons-round text-lg">add</span>
                </button>
              </div>
            </div>

            <div className="flex items-end space-x-2 mb-4">
              <p className="text-3xl font-black tracking-tight text-white">{waterGlasses}</p>
              <p className="text-sm font-bold text-slate-500 pb-1.5 uppercase tracking-widest">/ {user.dailyWaterGoal || 10} Glasses</p>
            </div>

            <div className="flex gap-1.5">
              {Array.from({ length: Math.max(waterGlasses, user.dailyWaterGoal || 10) }).map((_, i) => (
                <div 
                  key={i} 
                  className={`flex-1 h-2 rounded-full transition-all duration-500 ${
                    i < waterGlasses 
                      ? 'bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,0.5)]' 
                      : i < (user.dailyWaterGoal || 10) 
                      ? 'bg-white/5' 
                      : 'hidden'
                  }`}
                />
              ))}
            </div>

            {waterProgress >= 100 && (
              <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest mt-4 text-center animate-pulse">Hydration Target Met!</p>
            )}
          </div>
        </div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef } from 'react';
import { UserProfile } from '../types';

interface ProfileProps {
  user: UserProfile;
  onUpdate: (updates: Partial<UserProfile>) => void;
}

const PRESET_AVATARS = [
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Felix',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Aneka',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Tigger',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Spooky',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Buddy',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Cookie',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Milo',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Lilly',
];

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditingCalories, setIsEditingCalories] = useState(false);
  const [isEditingSteps, setIsEditingSteps] = useState(false);
  const [isEditingWater, setIsEditingWater] = useState(false);
  const [tempCalories, setTempCalories] = useState(user.dailyCalorieGoal);
  const [tempSteps, setTempSteps] = useState(user.dailyStepGoal);
  const [tempWater, setTempWater] = useState(user.dailyWaterGoal || 10);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isIncomplete = !user.dailyCalorieGoal || !user.dailyStepGoal || !user.weight || !user.targetWeight || !user.dailyWaterGoal;

  const goals = [
    { id: 'Cut', icon: 'trending_down', label: 'Lose Weight', desc: 'Calorie deficit' },
    { id: 'Maintain', icon: 'trending_flat', label: 'Stay Fit', desc: 'Equal intake' },
    { id: 'Bulk', icon: 'trending_up', label: 'Build Muscle', desc: 'Calorie surplus' },
  ];

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      if (!file.type.startsWith('image/')) {
        setUploadError('Please select a valid image file (PNG, JPG, etc.)');
        return;
      }
      if (file.size > MAX_FILE_SIZE) {
        setUploadError('Image is too large. Please select a file under 5MB.');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ avatarUrl: reader.result as string });
        setIsModalOpen(false);
      };
      reader.onerror = () => {
        setUploadError('Error reading file. Please try again.');
      };
      reader.readAsDataURL(file);
    }
  };

  const selectPreset = (url: string) => {
    setUploadError(null);
    onUpdate({ avatarUrl: url });
    setIsModalOpen(false);
  };

  const generateNewDiceBear = () => {
    setUploadError(null);
    const randomSeed = Math.random().toString(36).substring(7);
    onUpdate({ avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=${randomSeed}` });
    setIsModalOpen(false);
  };

  const handleSaveCalories = () => {
    onUpdate({ dailyCalorieGoal: tempCalories });
    setIsEditingCalories(false);
  };

  const handleSaveSteps = () => {
    onUpdate({ dailyStepGoal: tempSteps });
    setIsEditingSteps(false);
  };

  const handleSaveWater = () => {
    onUpdate({ dailyWaterGoal: tempWater });
    setIsEditingWater(false);
  };

  const openModal = () => {
    setUploadError(null);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col items-center text-center">
        <div className="relative group mb-4">
           <div className="absolute -inset-1 bg-gradient-to-tr from-primary to-primary/20 rounded-[2rem] blur opacity-25 group-hover:opacity-50 transition duration-500"></div>
           <div className="relative w-28 h-28 rounded-[2rem] bg-background-dark border-2 border-white/5 p-1 shadow-2xl overflow-hidden">
              <img 
                src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} 
                alt="Profile" 
                className="w-full h-full rounded-[1.8rem] bg-surface-dark object-cover" 
              />
              <button 
                onClick={openModal}
                className="absolute -bottom-2 -right-2 w-10 h-10 bg-primary rounded-2xl flex items-center justify-center text-black shadow-lg border-4 border-background-dark active:scale-90 transition-transform"
              >
                <span className="material-icons-round text-xl">camera_alt</span>
              </button>
           </div>
        </div>
        <h1 className="text-2xl font-black tracking-tight">{user.name}</h1>
        <p className="text-sm text-slate-500 font-medium">NutriVision Free Plan</p>
      </header>

      {/* Completion Prompt */}
      {isIncomplete && (
        <div className="bg-primary/10 border border-primary/20 rounded-[2rem] p-5 flex items-center gap-4 animate-in fade-in slide-in-from-top-4 duration-700 mx-1">
          <div className="w-12 h-12 rounded-2xl bg-primary/20 flex items-center justify-center text-primary shrink-0">
            <span className="material-icons-round text-2xl">priority_high</span>
          </div>
          <div className="flex-1">
            <p className="text-[11px] font-black text-primary uppercase tracking-[0.15em]">Setup Incomplete</p>
            <p className="text-[10px] text-white/60 font-bold leading-relaxed mt-1">
              Add your targets and weight below. Complete data allows the AI to give you 100% accurate macro scores.
            </p>
          </div>
        </div>
      )}

      {/* Avatar Customization Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass-card w-full max-sm rounded-[2.5rem] p-6 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden relative">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-black tracking-tight text-white">Choose Avatar</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-white/40 hover:text-white transition-colors">
                <span className="material-icons-round text-lg">close</span>
              </button>
            </div>

            <div className="space-y-6">
              {uploadError && (
                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 animate-in shake duration-300">
                  <span className="material-icons-round text-red-400 text-sm">error_outline</span>
                  <p className="text-[10px] font-bold text-red-400 uppercase tracking-wider">{uploadError}</p>
                </div>
              )}

              <button 
                onClick={() => fileInputRef.current?.click()}
                className={`w-full flex items-center p-4 bg-primary/10 border border-primary/20 rounded-2xl group active:scale-[0.98] transition-all ${uploadError ? 'ring-1 ring-red-500/50' : ''}`}
              >
                <div className="w-10 h-10 rounded-xl bg-primary text-black flex items-center justify-center mr-4">
                  <span className="material-icons-round">upload</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-primary uppercase tracking-wider">Upload Photo</p>
                  <p className="text-[10px] text-slate-500 font-bold">Select from your gallery (Max 5MB)</p>
                </div>
                <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
              </button>

              <div className="space-y-3">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Premium Presets</p>
                <div className="grid grid-cols-4 gap-3">
                  {PRESET_AVATARS.map((url, i) => (
                    <button 
                      key={i} 
                      onClick={() => selectPreset(url)}
                      className={`aspect-square rounded-xl bg-white/5 border-2 transition-all active:scale-90 ${user.avatarUrl === url ? 'border-primary' : 'border-transparent hover:border-white/10'}`}
                    >
                      <img src={url} alt={`Preset ${i}`} className="w-full h-full p-1" />
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={generateNewDiceBear}
                className="w-full flex items-center p-4 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors group"
              >
                <div className="w-10 h-10 rounded-xl bg-white/10 text-white/60 flex items-center justify-center mr-4 group-hover:text-primary transition-colors">
                  <span className="material-icons-round">casino</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-white/80 uppercase tracking-wider">Surprise Me</p>
                  <p className="text-[10px] text-slate-500 font-bold">Generate a random character</p>
                </div>
              </button>
            </div>
          </div>
        </div>
      )}

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Active Goal</h2>
        <div className="grid grid-cols-1 gap-3">
          {goals.map((g) => (
            <button
              key={g.id}
              onClick={() => onUpdate({ goal: g.id as any })}
              className={`flex items-center p-4 rounded-3xl border transition-all ${
                user.goal === g.id 
                  ? 'bg-primary/10 border-primary shadow-[0_0_20px_rgba(19,236,55,0.1)]' 
                  : 'bg-white/5 border-white/5 hover:border-white/10'
              }`}
            >
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 ${user.goal === g.id ? 'bg-primary text-black' : 'bg-white/5 text-slate-500'}`}>
                <span className="material-icons-round text-2xl">{g.icon}</span>
              </div>
              <div className="text-left flex-1">
                <p className={`font-black tracking-tight ${user.goal === g.id ? 'text-primary' : 'text-white'}`}>{g.label}</p>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{g.desc}</p>
              </div>
              {user.goal === g.id && (
                <span className="material-icons-round text-primary">check_circle</span>
              )}
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Daily Targets</h2>
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 space-y-6">
          <div className="flex justify-between items-start">
            <div 
              className="cursor-pointer group" 
              onClick={() => {
                if (!isEditingCalories) {
                  setTempCalories(user.dailyCalorieGoal);
                  setIsEditingCalories(true);
                }
              }}
            >
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-primary transition-colors">Calories</p>
              {isEditingCalories ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input 
                    type="number"
                    value={tempCalories}
                    autoFocus
                    onChange={(e) => setTempCalories(Number(e.target.value))}
                    className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white"
                  />
                  <button 
                    onClick={handleSaveCalories}
                    className="w-8 h-8 rounded-lg bg-primary text-black flex items-center justify-center active:scale-90"
                  >
                    <span className="material-icons-round text-sm">check</span>
                  </button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-primary transition-colors">
                  {user.dailyCalorieGoal || 0} <span className="text-xs font-medium text-slate-500 ml-1">kcal</span>
                </p>
              )}
            </div>
            {!isEditingCalories && (
              <button 
                onClick={() => {
                  setTempCalories(user.dailyCalorieGoal);
                  setIsEditingCalories(true);
                }}
                className="text-primary text-xs font-black uppercase tracking-widest bg-primary/10 px-4 py-2 rounded-xl active:scale-95 transition-all"
              >
                Adjust
              </button>
            )}
          </div>

          <div className="flex justify-between items-start pt-6 border-t border-white/5">
            <div 
              className="cursor-pointer group"
              onClick={() => {
                if (!isEditingSteps) {
                  setTempSteps(user.dailyStepGoal);
                  setIsEditingSteps(true);
                }
              }}
            >
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-primary transition-colors">Step Goal</p>
              {isEditingSteps ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input 
                    type="number"
                    value={tempSteps}
                    autoFocus
                    onChange={(e) => setTempSteps(Number(e.target.value))}
                    className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white"
                  />
                  <button 
                    onClick={handleSaveSteps}
                    className="w-8 h-8 rounded-lg bg-primary text-black flex items-center justify-center active:scale-90"
                  >
                    <span className="material-icons-round text-sm">check</span>
                  </button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-primary transition-colors">
                  {user.dailyStepGoal || 0} <span className="text-xs font-medium text-slate-500 ml-1">steps</span>
                </p>
              )}
            </div>
            {!isEditingSteps && (
              <button 
                onClick={() => {
                  setTempSteps(user.dailyStepGoal);
                  setIsEditingSteps(true);
                }}
                className="text-primary text-xs font-black uppercase tracking-widest bg-primary/10 px-4 py-2 rounded-xl active:scale-95 transition-all"
              >
                Adjust
              </button>
            )}
          </div>

          <div className="flex justify-between items-start pt-6 border-t border-white/5">
            <div 
              className="cursor-pointer group"
              onClick={() => {
                if (!isEditingWater) {
                  setTempWater(user.dailyWaterGoal || 10);
                  setIsEditingWater(true);
                }
              }}
            >
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-blue-400 transition-colors">Water Goal</p>
              {isEditingWater ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input 
                    type="number"
                    value={tempWater}
                    autoFocus
                    onChange={(e) => setTempWater(Number(e.target.value))}
                    className="bg-white/5 border border-blue-400/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-blue-400 text-white"
                  />
                  <button 
                    onClick={handleSaveWater}
                    className="w-8 h-8 rounded-lg bg-blue-400 text-white flex items-center justify-center active:scale-90"
                  >
                    <span className="material-icons-round text-sm">check</span>
                  </button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-blue-400 transition-colors">
                  {user.dailyWaterGoal || 10} <span className="text-xs font-medium text-slate-500 ml-1">glasses</span>
                </p>
              )}
            </div>
            {!isEditingWater && (
              <button 
                onClick={() => {
                  setTempWater(user.dailyWaterGoal || 10);
                  setIsEditingWater(true);
                }}
                className="text-blue-400 text-xs font-black uppercase tracking-widest bg-blue-400/10 px-4 py-2 rounded-xl active:scale-95 transition-all"
              >
                Adjust
              </button>
            )}
          </div>

          <div className="grid grid-cols-2 gap-6 pt-6 border-t border-white/5">
            <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Current Weight</p>
              <p className="text-lg font-black">{user.weight || 0} <span className="text-xs font-medium text-slate-500 ml-1">kg</span></p>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Target Weight</p>
              <p className="text-lg font-black text-primary">{user.targetWeight || 0} <span className="text-xs font-medium text-slate-500 ml-1">kg</span></p>
            </div>
          </div>
        </div>
      </section>

      <section className="space-y-3 pb-10">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Settings & Sync</h2>
        {[
          { icon: 'notifications', label: 'Reminders & Notifications', color: 'text-blue-400' },
          { icon: 'health_and_safety', label: 'Apple Health / Google Fit', color: 'text-red-400' },
          { icon: 'share', label: 'Invite Friends', color: 'text-orange-400' },
        ].map((item, i) => (
          <button 
            key={i} 
            className="w-full flex items-center p-4 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors group"
          >
            <span className={`material-icons-round mr-4 ${item.color}`}>{item.icon}</span>
            <span className="text-sm font-bold text-white/80 group-hover:text-white">{item.label}</span>
            <span className="material-icons-round ml-auto text-white/10 group-hover:text-white/30 text-lg">chevron_right</span>
          </button>
        ))}
      </section>
    </div>
  );
};

