import React, { useMemo } from 'react';
import { FoodEntry, UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  entries: FoodEntry[];
  waterGlasses: number;
  setWaterGlasses: (val: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, entries, waterGlasses, setWaterGlasses }) => {
  const consumed = entries.reduce((acc, entry) => acc + entry.calories, 0);
  const isSurplus = consumed > user.dailyCalorieGoal;
  const isGoalReached = consumed >= user.dailyCalorieGoal * 0.9 && consumed <= user.dailyCalorieGoal;
  const remaining = Math.max(0, user.dailyCalorieGoal - consumed);
  const surplus = isSurplus ? consumed - user.dailyCalorieGoal : 0;

  const progressPercent = Math.min(100, (consumed / user.dailyCalorieGoal) * 100);

  const totalMacros = useMemo(() => entries.reduce((acc, e) => ({
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
    fi: acc.fi + (e.fiber || 0),
  }), { p: 0, c: 0, f: 0, fi: 0 }), [entries]);

  const stepProgress = Math.min(100, (user.currentSteps / user.dailyStepGoal) * 100);
  const waterProgress = Math.min(100, (waterGlasses / (user.dailyWaterGoal || 10)) * 100);

  const getSuggestions = () => {
    const tips = [];
    const proteinDeficit = user.macros.protein - totalMacros.p;
    if (proteinDeficit > 20) {
      tips.push({
        icon: 'egg',
        text: `You need ${Math.round(proteinDeficit)}g more protein. Try a Greek yogurt or some paneer.`,
        color: 'text-primary'
      });
    }
    const fiberDeficit = user.macros.fiber - totalMacros.fi;
    if (fiberDeficit > 10) {
      tips.push({
        icon: 'eco',
        text: `Fiber check: Adding flax seeds or an apple will help digestion today.`,
        color: 'text-green-400'
      });
    }
    if (consumed > user.dailyCalorieGoal * 0.9 && !isSurplus) {
      tips.push({
        icon: 'verified',
        text: `Calorie precision! You are perfectly hitting your target for ${user.goal}.`,
        color: 'text-primary'
      });
    }
    if (waterGlasses < (user.dailyWaterGoal || 10) * 0.5) {
      tips.push({
        icon: 'water_drop',
        text: `Metabolism needs water. Drink more to reach your hydration goal.`,
        color: 'text-blue-400'
      });
    }
    return tips.length > 0 ? tips : [{ icon: 'verified', text: `Spot on! You are executing your plan flawlessly.`, color: 'text-primary' }];
  };

  const suggestions = useMemo(() => getSuggestions(), [totalMacros, consumed, waterGlasses, user]);

  const mainSize = 200;
  const mainCenter = mainSize / 2;
  const mainRadius = 85;
  const mainCircumference = 2 * Math.PI * mainRadius;
  const mainOffset = mainCircumference - (progressPercent / 100) * mainCircumference;

  const MacroCard = ({ 
    label, 
    current, 
    goal, 
    color, 
    icon 
  }: { 
    label: string, 
    current: number, 
    goal: number, 
    color: string, 
    icon: string 
  }) => {
    const macroPercent = Math.min(100, (current / goal) * 100);
    const smallSize = 70;
    const smallCenter = smallSize / 2;
    const smallRadius = 30;
    const smallCircumference = 2 * Math.PI * smallRadius;
    const smallOffset = smallCircumference - (macroPercent / 100) * smallCircumference;

    return (
      <div className="glass-card rounded-[2.2rem] p-5 flex flex-col items-center border border-white/5 shadow-sm transition-all hover:bg-white/[0.08] hover:-translate-y-1 duration-300 group">
        <div className="relative w-[70px] h-[70px] mb-4">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${smallSize} ${smallSize}`}>
            <circle 
              className="text-white/[0.03]" 
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeWidth="6" 
            />
            <circle 
              className={color} 
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeDasharray={smallCircumference} 
              strokeDashoffset={smallOffset} 
              strokeLinecap="round" 
              strokeWidth="6" 
              style={{ transition: 'stroke-dashoffset 1.2s cubic-bezier(0.4, 0, 0.2, 1)' }} 
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className={`material-icons-round text-xl ${color} group-hover:scale-125 transition-transform duration-300`}>{icon}</span>
          </div>
        </div>
        <div className="text-center w-full">
          <p className="text-[9px] font-black uppercase tracking-[0.25em] text-white/30 mb-1">{label}</p>
          <p className="text-sm font-black text-white">{Math.round(current)}g</p>
          <div className="flex items-center justify-center mt-1.5 space-x-1.5">
             <div className={`w-1.5 h-1.5 rounded-full ${color.replace('text-', 'bg-')} shadow-[0_0_5px_currentColor]`}></div>
             <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Goal: {goal}g</p>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-7 pb-10">
      <header className="flex justify-between items-center">
        <div>
          <p className="text-[10px] font-bold text-primary uppercase tracking-[0.2em] mb-1">
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
          </p>
          <h1 className="text-2xl font-black tracking-tight">Hey, {user.name.split(' ')[0]}!</h1>
        </div>
        <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-primary/20 to-primary/5 p-[1px] shadow-lg">
          <div className="w-full h-full rounded-[14px] bg-background-dark overflow-hidden flex items-center justify-center">
            <img src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
      </header>

      <section className="animate-in fade-in slide-in-from-top-4 duration-500">
        <div className="bg-primary/10 border border-primary/20 rounded-2xl p-4 relative overflow-hidden">
          <div className="absolute -right-4 -top-4 opacity-10">
            <span className="material-icons-round text-7xl">psychology</span>
          </div>
          <div className="flex items-start space-x-3">
            <div className={`p-2 rounded-xl bg-background-dark/50 ${suggestions[0].color}`}>
              <span className="material-icons-round text-xl">{suggestions[0].icon}</span>
            </div>
            <div className="flex-1 pr-4">
              <h3 className="text-[10px] font-black uppercase tracking-widest text-primary mb-1">AI Daily Engine</h3>
              <p className="text-sm font-medium leading-relaxed text-white/90 italic">"{suggestions[0].text}"</p>
            </div>
          </div>
        </div>
      </section>

      <section className="glass-card rounded-[2.5rem] p-8 flex flex-col items-center justify-center relative overflow-hidden border border-white/5 shadow-2xl">
        {isGoalReached && (
          <div className="absolute inset-0 bg-primary/5 animate-pulse pointer-events-none"></div>
        )}
        <div className="relative w-56 h-56 flex items-center justify-center">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${mainSize} ${mainSize}`}>
            <circle className="text-white/5" cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeWidth="14" />
            <circle className={isSurplus ? "text-red-500" : isGoalReached ? "text-primary" : "text-primary/60"} cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeDasharray={mainCircumference} strokeDashoffset={mainOffset} strokeLinecap="round" strokeWidth="14" style={{ transition: 'stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1)', filter: `drop-shadow(0 0 10px ${isSurplus ? 'rgba(239,68,68,0.4)' : 'rgba(19,236,55,0.4)'})` }} />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
            {isSurplus ? (
              <>
                <span className="text-4xl font-black text-red-500 tabular-nums">+{surplus.toLocaleString()}</span>
                <span className="text-[10px] text-red-400 font-bold uppercase tracking-widest mt-1">Surplus kcal</span>
              </>
            ) : (
              <>
                <span className="text-5xl font-black text-white tabular-nums tracking-tighter">{remaining.toLocaleString()}</span>
                <span className="text-[10px] text-white/40 font-bold uppercase tracking-[0.2em] mt-1">kcal left</span>
              </>
            )}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4 w-full mt-10 pt-8 border-t border-white/5">
          <div className="text-center">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1">Logged</p>
            <p className="text-xl font-bold text-white">{consumed.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span></p>
          </div>
          <div className="text-center">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1">Target</p>
            <p className="text-xl font-bold text-white">{user.dailyCalorieGoal.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span></p>
          </div>
        </div>
      </section>

      <section>
        <div className="flex justify-between items-center mb-5 px-1">
          <h2 className="text-[11px] font-black uppercase tracking-[0.25em] text-white/40">Nutrients Today</h2>
          <span className="material-icons-round text-[14px] text-white/40 cursor-pointer">info</span>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <MacroCard label="Protein" current={totalMacros.p} goal={user.macros.protein} icon="egg" color="text-emerald-400" />
          <MacroCard label="Carbs" current={totalMacros.c} goal={user.macros.carbs} icon="grain" color="text-amber-400" />
          <MacroCard label="Fats" current={totalMacros.f} goal={user.macros.fats} icon="opacity" color="text-orange-400" />
          <MacroCard label="Fiber" current={totalMacros.fi} goal={user.macros.fiber} icon="eco" color="text-lime-400" />
        </div>
      </section>

      <section className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Step Tracker Card */}
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group">
          <div className="absolute -right-4 -bottom-4 opacity-[0.03] group-hover:scale-110 transition-transform duration-700">
             <span className="material-icons-round text-8xl">directions_run</span>
          </div>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-3">
               <div className="w-10 h-10 bg-primary/20 rounded-2xl flex items-center justify-center"><span className="material-icons-round text-primary text-xl">directions_run</span></div>
               <span className="text-[11px] font-black text-white/30 uppercase tracking-[0.2em]">Steps</span>
            </div>
            {stepProgress >= 100 && <span className="material-icons-round text-primary text-lg">verified</span>}
          </div>
          <div className="flex items-end space-x-2">
            <p className="text-3xl font-black tracking-tight">{user.currentSteps.toLocaleString()}</p>
            <p className="text-sm font-bold text-slate-500 pb-1.5 uppercase tracking-widest">/ {user.dailyStepGoal.toLocaleString()}</p>
          </div>
          <div className="mt-4 w-full h-2 bg-white/5 rounded-full overflow-hidden">
            <div className="h-full bg-primary rounded-full transition-all duration-1000 shadow-[0_0_10px_rgba(19,236,55,0.4)]" style={{ width: `${stepProgress}%` }}></div>
          </div>
        </div>

        {/* Hydration Tracker Card */}
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group">
          <div 
            className="absolute inset-0 bg-blue-500/5 transition-all duration-1000 origin-bottom" 
            style={{ transform: `scaleY(${waterProgress / 100})` }}
          />
          <div className="relative z-10">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-3">
                 <div className="w-10 h-10 bg-blue-500/20 rounded-2xl flex items-center justify-center"><span className="material-icons-round text-blue-400 text-xl">water_drop</span></div>
                 <span className="text-[11px] font-black text-white/30 uppercase tracking-[0.2em]">Hydration</span>
              </div>
              <div className="flex space-x-2">
                <button 
                  onClick={() => setWaterGlasses(Math.max(0, waterGlasses - 1))} 
                  className="w-8 h-8 rounded-xl bg-white/5 border border-white/5 flex items-center justify-center text-slate-500 hover:text-white transition-colors"
                >
                  <span className="material-icons-round text-lg">remove</span>
                </button>
                <button 
                  onClick={() => setWaterGlasses(waterGlasses + 1)} 
                  className="w-8 h-8 rounded-xl bg-blue-500/20 border border-blue-500/20 flex items-center justify-center text-blue-400 hover:bg-blue-500/30 transition-all active:scale-90"
                >
                  <span className="material-icons-round text-lg">add</span>
                </button>
              </div>
            </div>

            <div className="flex items-end space-x-2 mb-4">
              <p className="text-3xl font-black tracking-tight text-white">{waterGlasses}</p>
              <p className="text-sm font-bold text-slate-500 pb-1.5 uppercase tracking-widest">/ {user.dailyWaterGoal || 10} Glasses</p>
            </div>

            <div className="flex gap-1.5">
              {Array.from({ length: Math.max(waterGlasses, user.dailyWaterGoal || 10) }).map((_, i) => (
                <div 
                  key={i} 
                  className={`flex-1 h-2 rounded-full transition-all duration-500 ${
                    i < waterGlasses 
                      ? 'bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,0.5)]' 
                      : i < (user.dailyWaterGoal || 10) 
                      ? 'bg-white/5' 
                      : 'hidden'
                  }`}
                />
              ))}
            </div>

            {waterProgress >= 100 && (
              <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest mt-4 text-center animate-pulse">Hydration Target Met!</p>
            )}
          </div>
        </div>
      </section>
    </div>
  );
};

