        )}
      </section>

      <div className="pb-10"></div>
    </div>
  );
}

{
  "name": "NutriVision AI",
  "description": "An AI-powered food nutrition and fitness tracking app with real-time food recognition and personalized analytics.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Analytics from './components/Analytics';
import CameraScan from './components/CameraScan';
import Diary from './components/Diary';
import Profile from './components/Profile';
import FoodGuide from './components/FoodGuide';
import { View, UserProfile, FoodEntry, NutritionData } from './types';

const STORAGE_KEYS = {
  PROFILE: 'nv_profile_local',
  ENTRIES: 'nv_entries_local',
  WATER: 'nv_water_local'
};

const PLACEHOLDER_ENTRIES: FoodEntry[] = [
  {
    id: '1',
    name: 'Avocado Toast with Egg',
    calories: 450,
    protein: 18,
    carbs: 42,
    fats: 24,
    fiber: 8,
    portionSize: '2 slices',
    timestamp: new Date()
  },
  {
    id: '2',
    name: 'Grilled Chicken Salad',
    calories: 380,
    protein: 35,
    carbs: 12,
    fats: 20,
    fiber: 5,
    portionSize: '1 bowl',
    timestamp: new Date()
  },
  {
    id: '3',
    name: 'Greek Yogurt with Berries',
    calories: 180,
    protein: 15,
    carbs: 22,
    fats: 4,
    fiber: 3,
    portionSize: '1 container',
    timestamp: new Date()
  }
];

const DEFAULT_USER_STATE: UserProfile = {
  name: 'Alex Thompson',
  goal: 'Maintain',
  dailyCalorieGoal: 2200,
  dailyStepGoal: 10000,
  dailyWaterGoal: 10,
  currentSteps: 6420,
  weight: 72.5,
  targetWeight: 70.0,
  bmi: 23.4,
  bodyFat: 18.5,
  macros: { protein: 150, carbs: 220, fats: 70, fiber: 30 },
  avatarUrl: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Alex'
};

export default function App() {
  const [view, setView] = useState<View>('home');
  const [waterGlasses, setWaterGlasses] = useState(5);
  const [user, setUser] = useState<UserProfile>(DEFAULT_USER_STATE);
  const [entries, setEntries] = useState<FoodEntry[]>(PLACEHOLDER_ENTRIES);

  // Load data on mount
  useEffect(() => {
    const storedProfile = localStorage.getItem(STORAGE_KEYS.PROFILE);
    const storedEntries = localStorage.getItem(STORAGE_KEYS.ENTRIES);
    const storedWater = localStorage.getItem(STORAGE_KEYS.WATER);

    if (storedProfile) {
      setUser(JSON.parse(storedProfile));
    }

    if (storedEntries) {
      const parsed = JSON.parse(storedEntries).map((e: any) => ({
        ...e,
        timestamp: new Date(e.timestamp)
      }));
      setEntries(parsed);
    }

    if (storedWater) {
      setWaterGlasses(parseInt(storedWater, 10) || 0);
    }
  }, []);

  // Persist water glasses
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.WATER, waterGlasses.toString());
  }, [waterGlasses]);

  const handleAddEntry = (data: NutritionData & { multiplier?: number }) => {
    const newEntry: FoodEntry = {
      id: Date.now().toString(),
      name: data.foodName,
      calories: data.calories,
      protein: data.protein,
      carbs: data.carbs,
      fats: data.fats,
      fiber: data.fiber || 0,
      portionSize: data.portionDescription || '1 serving',
      timestamp: new Date()
    };

    const updatedEntries = [newEntry, ...entries];
    setEntries(updatedEntries);
    localStorage.setItem(STORAGE_KEYS.ENTRIES, JSON.stringify(updatedEntries));
    setView('home');
  };

  const handleDeleteEntry = (id: string) => {
    const updatedEntries = entries.filter(e => e.id !== id);
    setEntries(updatedEntries);
    localStorage.setItem(STORAGE_KEYS.ENTRIES, JSON.stringify(updatedEntries));
  };

  const updateUser = (updates: Partial<UserProfile>) => {
    const updatedUser = { ...user, ...updates };
    setUser(updatedUser);
    localStorage.setItem(STORAGE_KEYS.PROFILE, JSON.stringify(updatedUser));
  };

  const renderContent = () => {
    switch (view) {
      case 'home': return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
      case 'analytics': return <Analytics user={user} />;
      case 'diary': return <Diary entries={entries} onAddManualEntry={handleAddEntry} onDeleteEntry={handleDeleteEntry} />;
      case 'profile': return <Profile user={user} onUpdate={updateUser} />;
      case 'recipes': return <FoodGuide user={user} />;
      case 'camera': return <CameraScan onAddEntry={handleAddEntry} onClose={() => setView('home')} />;
      default: return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
    }
  };

  return (
    <Layout activeView={view} onViewChange={setView}>
      {renderContent()}
    </Layout>
  );
}

import React, { useState, useMemo } from 'react';
import { FoodEntry, NutritionData } from '../types';

interface DiaryProps {
  entries: FoodEntry[];
  onAddManualEntry: (data: NutritionData) => void;
  onDeleteEntry: (id: string) => void;
}

export default function Diary({ entries, onAddManualEntry, onDeleteEntry }: DiaryProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  // Manual Entry Form State
  const [formData, setFormData] = useState<NutritionData>({
    foodName: '',
    calories: 0,
    protein: 0,
    carbs: 0,
    fats: 0,
    fiber: 0,
    portionDescription: ''
  });

  // Calculate grouped entries and summaries for the last 7 days
  const weeklyHistory = useMemo(() => {
    const history = [];
    const today = new Date();

    for (let i = 0; i < 7; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];

      const dayEntries = entries.filter(e => {
        const entryDate = new Date(e.timestamp).toISOString().split('T')[0];
        return entryDate === dateStr && 
               e.name.toLowerCase().includes(searchQuery.toLowerCase());
      }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

      const totals = dayEntries.reduce((acc, e) => ({
        cal: acc.cal + e.calories,
        p: acc.p + e.protein,
        c: acc.c + e.carbs,
        f: acc.f + e.fats,
      }), { cal: 0, p: 0, c: 0, f: 0 });

      if (dayEntries.length > 0 || !searchQuery) {
        history.push({
          date: dateStr,
          label: i === 0 ? 'Today' : i === 1 ? 'Yesterday' : d.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' }),
          dayNum: d.getDate(),
          entries: dayEntries,
          totals
        });
      }
    }
    return history;
  }, [entries, searchQuery]);

  const handleSaveManual = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.foodName) return;
    onAddManualEntry(formData);
    setIsAdding(false);
    setFormData({ foodName: '', calories: 0, protein: 0, carbs: 0, fats: 0, fiber: 0, portionDescription: '' });
  };

  const initiateDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setConfirmDeleteId(id);
  };

  const confirmDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    onDeleteEntry(id);
    setConfirmDeleteId(null);
  };

  const cancelDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    setConfirmDeleteId(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
