import React, { useMemo } from 'react';
import { FoodEntry, UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  entries: FoodEntry[];
  waterGlasses: number;
  setWaterGlasses: (val: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, entries, waterGlasses, setWaterGlasses }) => {
  const consumed = entries.reduce((acc, entry) => acc + entry.calories, 0);
  const isSurplus = consumed > user.dailyCalorieGoal;
  const isGoalReached = consumed >= user.dailyCalorieGoal * 0.9 && consumed <= user.dailyCalorieGoal;
  const remaining = Math.max(0, user.dailyCalorieGoal - consumed);
  const surplus = isSurplus ? consumed - user.dailyCalorieGoal : 0;

  const progressPercent = Math.min(100, (consumed / user.dailyCalorieGoal) * 100);

  const totalMacros = useMemo(() => entries.reduce((acc, e) => ({
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
    fi: acc.fi + (e.fiber || 0),
  }), { p: 0, c: 0, f: 0, fi: 0 }), [entries]);

  const stepProgress = Math.min(100, (user.currentSteps / user.dailyStepGoal) * 100);
  const waterProgress = Math.min(100, (waterGlasses / (user.dailyWaterGoal || 10)) * 100);

  const getSuggestions = () => {
    const tips = [];
    const proteinDeficit = user.macros.protein - totalMacros.p;
    if (proteinDeficit > 20) {
      tips.push({
        icon: 'egg',
        text: `You need ${Math.round(proteinDeficit)}g more protein. Try a Greek yogurt or some paneer.`,
        color: 'text-primary'
      });
    }
    const fiberDeficit = user.macros.fiber - totalMacros.fi;
    if (fiberDeficit > 10) {
      tips.push({
        icon: 'eco',
        text: `Fiber check: Adding flax seeds or an apple will help digestion today.`,
        color: 'text-green-400'
      });
    }
    if (consumed > user.dailyCalorieGoal * 0.9 && !isSurplus) {
      tips.push({
        icon: 'verified',
        text: `Calorie precision! You are perfectly hitting your target for ${user.goal}.`,
        color: 'text-primary'
      });
    }
    if (waterGlasses < (user.dailyWaterGoal || 10) * 0.5) {
      tips.push({
        icon: 'water_drop',
        text: `Metabolism needs water. Drink more to reach your hydration goal.`,
        color: 'text-blue-400'
      });
    }
    return tips.length > 0 ? tips : [{ icon: 'verified', text: `Spot on! You are executing your plan flawlessly.`, color: 'text-primary' }];
  };

  const suggestions = useMemo(() => getSuggestions(), [totalMacros, consumed, waterGlasses, user]);

  const mainSize = 200;
  const mainCenter = mainSize / 2;
  const mainRadius = 85;
  const mainCircumference = 2 * Math.PI * mainRadius;
  const mainOffset = mainCircumference - (progressPercent / 100) * mainCircumference;

  const MacroCard = ({ 
    label, 
    current, 
    goal, 
    color, 
    icon 
  }: { 
    label: string, 
    current: number, 
    goal: number, 
    color: string, 
    icon: string 
  }) => {
    const macroPercent = Math.min(100, (current / goal) * 100);
    const smallSize = 70;
    const smallCenter = smallSize / 2;
    const smallRadius = 30;
    const smallCircumference = 2 * Math.PI * smallRadius;
    const smallOffset = smallCircumference - (macroPercent / 100) * smallCircumference;

    return (
      <div className="glass-card rounded-[2.2rem] p-5 flex flex-col items-center border border-white/5 shadow-sm transition-all hover:bg-white/[0.08] hover:-translate-y-1 duration-300 group">
        <div className="relative w-[70px] h-[70px] mb-4">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${smallSize} ${smallSize}`}>
            <circle 
              className="text-white/[0.03]" 
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeWidth="6" 
            />
            <circle 
              className={color} 
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeDasharray={smallCircumference} 
              strokeDashoffset={smallOffset} 
              strokeLinecap="round" 
              strokeWidth="6" 
              style={{ transition: 'stroke-dashoffset 1.2s cubic-bezier(0.4, 0, 0.2, 1)' }} 
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className={`material-icons-round text-xl ${color} group-hover:scale-125 transition-transform duration-300`}>{icon}</span>
          </div>
        </div>
        <div className="text-center w-full">
          <p className="text-[9px] font-black uppercase tracking-[0.25em] text-white/30 mb-1">{label}</p>
          <p className="text-sm font-black text-white">{Math.round(current)}g</p>
          <div className="flex items-center justify-center mt-1.5 space-x-1.5">
             <div className={`w-1.5 h-1.5 rounded-full ${color.replace('text-', 'bg-')} shadow-[0_0_5px_currentColor]`}></div>
             <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Goal: {goal}g</p>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-7 pb-10">
      <header className="flex justify-between items-center">
        <div>
          <p className="text-[10px] font-bold text-primary uppercase tracking-[0.2em] mb-1">
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
          </p>
          <h1 className="text-2xl font-black tracking-tight">Hey, {user.name.split(' ')[0]}!</h1>
        </div>
        <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-primary/20 to-primary/5 p-[1px] shadow-lg">
          <div className="w-full h-full rounded-[14px] bg-background-dark overflow-hidden flex items-center justify-center">
            <img src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
      </header>

      <section className="animate-in fade-in slide-in-from-top-4 duration-500">
        <div className="bg-primary/10 border border-primary/20 rounded-2xl p-4 relative overflow-hidden">
          <div className="absolute -right-4 -top-4 opacity-10">
            <span className="material-icons-round text-7xl">psychology</span>
          </div>
          <div className="flex items-start space-x-3">
            <div className={`p-2 rounded-xl bg-background-dark/50 ${suggestions[0].color}`}>
              <span className="material-icons-round text-xl">{suggestions[0].icon}</span>
            </div>
            <div className="flex-1 pr-4">
              <h3 className="text-[10px] font-black uppercase tracking-widest text-primary mb-1">AI Daily Engine</h3>
              <p className="text-sm font-medium leading-relaxed text-white/90 italic">"{suggestions[0].text}"</p>
            </div>
          </div>
        </div>
      </section>

      <section className="glass-card rounded-[2.5rem] p-8 flex flex-col items-center justify-center relative overflow-hidden border border-white/5 shadow-2xl">
        {isGoalReached && (
          <div className="absolute inset-0 bg-primary/5 animate-pulse pointer-events-none"></div>
        )}
        <div className="relative w-56 h-56 flex items-center justify-center">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${mainSize} ${mainSize}`}>
            <circle className="text-white/5" cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeWidth="14" />
            <circle className={isSurplus ? "text-red-500" : isGoalReached ? "text-primary" : "text-primary/60"} cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeDasharray={mainCircumference} strokeDashoffset={mainOffset} strokeLinecap="round" strokeWidth="14" style={{ transition: 'stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1)', filter: `drop-shadow(0 0 10px ${isSurplus ? 'rgba(239,68,68,0.4)' : 'rgba(19,236,55,0.4)'})` }} />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
            {isSurplus ? (
              <>
                <span className="text-4xl font-black text-red-500 tabular-nums">+{surplus.toLocaleString()}</span>
                <span className="text-[10px] text-red-400 font-bold uppercase tracking-widest mt-1">Surplus kcal</span>
              </>
            ) : (
              <>
                <span className="text-5xl font-black text-white tabular-nums tracking-tighter">{remaining.toLocaleString()}</span>
                <span className="text-[10px] text-white/40 font-bold uppercase tracking-[0.2em] mt-1">kcal left</span>
              </>
            )}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4 w-full mt-10 pt-8 border-t border-white/5">
          <div className="text-center">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1">Logged</p>
            <p className="text-xl font-bold text-white">{consumed.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span></p>
          </div>
          <div className="text-center">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1">Target</p>
            <p className="text-xl font-bold text-white">{user.dailyCalorieGoal.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span></p>
          </div>
        </div>
      </section>

      <section>
        <div className="flex justify-between items-center mb-5 px-1">
          <h2 className="text-[11px] font-black uppercase tracking-[0.25em] text-white/40">Nutrients Today</h2>
          <span className="material-icons-round text-[14px] text-white/40 cursor-pointer">info</span>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <MacroCard label="Protein" current={totalMacros.p} goal={user.macros.protein} icon="egg" color="text-emerald-400" />
          <MacroCard label="Carbs" current={totalMacros.c} goal={user.macros.carbs} icon="grain" color="text-amber-400" />
          <MacroCard label="Fats" current={totalMacros.f} goal={user.macros.fats} icon="opacity" color="text-orange-400" />
          <MacroCard label="Fiber" current={totalMacros.fi} goal={user.macros.fiber} icon="eco" color="text-lime-400" />
        </div>
      </section>

      <section className="grid grid-cols-2 gap-4">
        {/* Step Tracker Card - Matches Screenshot Layout */}
        <div className="glass-card rounded-[2.2rem] p-6 border border-white/5 relative overflow-hidden group min-h-[140px] flex flex-col justify-between">
          <div className="flex items-center space-x-3 mb-2">
             <div className="w-10 h-10 bg-[#13ec37]/15 rounded-full flex items-center justify-center">
               <span className="material-icons-round text-[#13ec37] text-xl">directions_run</span>
             </div>
             <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em]">Steps</span>
          </div>

          <div className="absolute right-[-10px] bottom-[10px] opacity-[0.05] group-hover:scale-110 transition-transform duration-700">
             <span className="material-icons-round text-6xl">directions_run</span>
          </div>

          <div className="mt-auto">
            <div className="flex items-end space-x-1.5 mb-3">
              <p className="text-xl font-black tracking-tight text-white">{user.currentSteps.toLocaleString()}</p>
              <p className="text-[10px] font-bold text-white/30 pb-0.5 uppercase tracking-widest">/ {user.dailyStepGoal.toLocaleString()}</p>
            </div>
            <div className="w-full h-1.5 bg-white/5 rounded-full overflow-hidden">
              <div 
                className="h-full bg-[#13ec37] rounded-full transition-all duration-1000" 
                style={{ width: `${stepProgress}%` }}
              ></div>
            </div>
          </div>
        </div>

        {/* Hydration Tracker Card - Matches Screenshot Layout */}
        <div className="glass-card rounded-[2.2rem] p-6 border border-white/5 relative overflow-hidden group min-h-[140px] flex flex-col justify-between" onClick={() => setWaterGlasses(waterGlasses + 1)}>
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center space-x-3">
               <div className="w-10 h-10 bg-blue-500/20 rounded-full flex items-center justify-center">
                 <span className="material-icons-round text-blue-400 text-xl">water_drop</span>
               </div>
               <span className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em]">Hydration</span>
            </div>
            <button 
              onClick={(e) => {
                e.stopPropagation();
                setWaterGlasses(Math.max(0, waterGlasses - 1));
              }}
              className="w-8 h-8 rounded-full bg-white/5 border border-white/5 flex items-center justify-center text-white/40 hover:text-white transition-colors active:scale-90"
            >
              <span className="material-icons-round text-sm">remove</span>
            </button>
          </div>

          <div className="mt-auto">
            <div className="flex items-end space-x-1.5 mb-3">
              <p className="text-xl font-black tracking-tight text-white">{waterGlasses}</p>
              <p className="text-[10px] font-bold text-white/30 pb-0.5 uppercase tracking-widest">/ {user.dailyWaterGoal || 10} Glasses</p>
            </div>

            <div className="flex gap-1">
              {Array.from({ length: user.dailyWaterGoal || 10 }).map((_, i) => (
                <div 
                  key={i} 
                  className={`flex-1 h-1.5 rounded-full transition-all duration-500 ${
                    i < waterGlasses 
                      ? 'bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,0.5)]' 
                      : 'bg-white/5'
                  }`}
                />
              ))}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { FoodEntry, NutritionData } from '../types';

interface DiaryProps {
  entries: FoodEntry[];
  onAddManualEntry: (data: NutritionData) => void;
  onDeleteEntry: (id: string) => void;
}

export default function Diary({ entries, onAddManualEntry, onDeleteEntry }: DiaryProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const foodNameInputRef = useRef<HTMLInputElement>(null);

  // Manual Entry Form State
  const [formData, setFormData] = useState<NutritionData>({
    foodName: '',
    calories: 0,
    protein: 0,
    carbs: 0,
    fats: 0,
    fiber: 0,
    portionDescription: ''
  });

  // Automatically focus and select foodName field when modal opens
  useEffect(() => {
    if (isAdding) {
      // Small timeout to ensure the DOM element is rendered and transition has started
      const timer = setTimeout(() => {
        if (foodNameInputRef.current) {
          foodNameInputRef.current.focus();
          foodNameInputRef.current.select();
        }
      }, 50);
      return () => clearTimeout(timer);
    }
  }, [isAdding]);

  // Calculate grouped entries and summaries for the last 7 days
  const weeklyHistory = useMemo(() => {
    const history = [];
    const today = new Date();

    for (let i = 0; i < 7; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];

      const dayEntries = entries.filter(e => {
        const entryDate = new Date(e.timestamp).toISOString().split('T')[0];
        return entryDate === dateStr && 
               e.name.toLowerCase().includes(searchQuery.toLowerCase());
      }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

      const totals = dayEntries.reduce((acc, e) => ({
        cal: acc.cal + e.calories,
        p: acc.p + e.protein,
        c: acc.c + e.carbs,
        f: acc.f + e.fats,
      }), { cal: 0, p: 0, c: 0, f: 0 });

      if (dayEntries.length > 0 || !searchQuery) {
        history.push({
          date: dateStr,
          label: i === 0 ? 'Today' : i === 1 ? 'Yesterday' : d.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' }),
          dayNum: d.getDate(),
          entries: dayEntries,
          totals
        });
      }
    }
    return history;
  }, [entries, searchQuery]);

  const handleSaveManual = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.foodName) return;
    onAddManualEntry(formData);
    setIsAdding(false);
    setFormData({ foodName: '', calories: 0, protein: 0, carbs: 0, fats: 0, fiber: 0, portionDescription: '' });
  };

  const initiateDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setConfirmDeleteId(id);
  };

  const confirmDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    onDeleteEntry(id);
    setConfirmDeleteId(null);
  };

  const cancelDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    setConfirmDeleteId(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header className="space-y-6">
        <div className="flex justify-between items-center px-1">
          <div>
            <h1 className="text-2xl font-black tracking-tight">Food Diary</h1>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 mt-0.5">Week at a Glance</p>
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="w-10 h-10 rounded-2xl bg-primary text-black flex items-center justify-center shadow-lg active:scale-90 transition-transform fab-glow"
          >
            <span className="material-icons-round text-2xl">add</span>
          </button>
        </div>

        <div className="glass-card rounded-2xl p-4 flex items-center space-x-3 border border-white/5 focus-within:border-primary/50 transition-colors">
          <span className="material-icons-round text-slate-500 text-xl">search</span>
          <input 
            type="text" 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search your logs..."
            className="bg-transparent text-sm font-medium focus:outline-none w-full text-white placeholder:text-slate-600"
          />
        </div>
      </header>

      {/* Manual Entry Modal */}
      {isAdding && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="glass-card w-full max-w-[400px] rounded-[2.5rem] p-8 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center mb-8">
              <div>
                <h3 className="text-xl font-black tracking-tight">Quick Log</h3>
                <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mt-1">Manual Input</p>
              </div>
              <button onClick={() => setIsAdding(false)} className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 active:scale-90 transition-transform">
                <span className="material-icons-round">close</span>
              </button>
            </div>

            <form onSubmit={handleSaveManual} className="space-y-5">
              <div className="space-y-1.5">
                <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Food Name</label>
                <input 
                  ref={foodNameInputRef}
                  required
                  value={formData.foodName}
                  onChange={e => setFormData({...formData, foodName: e.target.value})}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                  placeholder="e.g. Avocado Toast"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Portion Description</label>
                <input 
                  value={formData.portionDescription}
                  onChange={e => setFormData({...formData, portionDescription: e.target.value})}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                  placeholder="e.g. 1 Large Plate, 250g"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Calories</label>
                  <input 
                    type="number"
                    value={formData.calories || ''}
                    onChange={e => setFormData({...formData, calories: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                    placeholder="0"
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Protein (g)</label>
                  <input 
                    type="number"
                    value={formData.protein || ''}
                    onChange={e => setFormData({...formData, protein: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                    placeholder="0"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Carbs (g)</label>
                  <input 
                    type="number"
                    value={formData.carbs || ''}
                    onChange={e => setFormData({...formData, carbs: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                    placeholder="0"
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Fats (g)</label>
                  <input 
                    type="number"
                    value={formData.fats || ''}
                    onChange={e => setFormData({...formData, fats: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                    placeholder="0"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Fiber (g)</label>
                <input 
                  type="number"
                  value={formData.fiber || ''}
                  onChange={e => setFormData({...formData, fiber: Number(e.target.value)})}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                  placeholder="0"
                />
              </div>

              <button 
                type="submit"
                className="w-full bg-primary text-black font-black py-5 rounded-[1.8rem] shadow-xl shadow-primary/20 mt-4 active:scale-[0.98] transition-all uppercase tracking-widest text-xs"
              >
                Log Entry
              </button>
            </form>
          </div>
        </div>
      )}

      {/* 7-Day History List */}
      <section className="space-y-10">
        {weeklyHistory.map((day) => (
          <div key={day.date} className="space-y-4">
            {/* Day Summary Header */}
            <div className="flex items-end justify-between px-1 sticky top-0 z-10 py-2 bg-background-dark/80 backdrop-blur-md border-b border-white/5">
              <div>
                <h2 className="text-lg font-black tracking-tight text-white">{day.label}</h2>
              </div>
              <div className="flex space-x-4">
                <div className="text-right">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest leading-none mb-1">Total</p>
                  <p className={`text-sm font-black ${day.totals.cal > 0 ? 'text-primary' : 'text-slate-700'}`}>{day.totals.cal} <span className="text-[8px] font-bold text-slate-600">kcal</span></p>
                </div>
                <div className="text-right border-l border-white/5 pl-4">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest leading-none mb-1">Protein</p>
                  <p className="text-sm font-black text-white/40">{Math.round(day.totals.p)}g</p>
                </div>
              </div>
            </div>

            {/* Entries for this Day */}
            {day.entries.length === 0 ? (
              <div className="py-6 flex items-center justify-center glass-card rounded-2xl border-dashed border-white/5 border-2">
                <p className="text-[10px] font-bold text-slate-600 uppercase tracking-widest">No entries logged</p>
              </div>
            ) : (
              <div className="space-y-3">
                {day.entries.map((entry) => (
                  <div key={entry.id} className="glass-card rounded-[1.8rem] p-5 flex items-center justify-between group active:scale-[0.98] transition-all border border-white/5 hover:bg-white/[0.05] hover:border-primary/20 relative overflow-hidden">
                    <div className="space-y-2 shrink overflow-hidden text-left relative z-10">
                      <div className="flex items-center space-x-3">
                        <div className="px-2 py-0.5 rounded-lg bg-primary/10 text-primary text-[9px] font-black uppercase tracking-widest">
                          {new Date(entry.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </div>
                        <h3 className="text-sm font-black text-white truncate group-hover:text-primary transition-colors">{entry.name}</h3>
                      </div>
                      <div className="flex items-center space-x-4">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">P {Math.round(entry.protein)}g</span>
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">C {Math.round(entry.carbs)}g</span>
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">F {Math.round(entry.fats)}g</span>
                      </div>
                    </div>

                    <div className="flex items-center space-x-4 relative z-10">
                      <div className="text-right shrink-0">
                        <p className="text-xl font-black text-primary leading-none tracking-tighter">{entry.calories}</p>
                        <p className="text-[8px] uppercase font-black text-slate-600 tracking-widest mt-1">kcal</p>
                      </div>

                      {confirmDeleteId === entry.id ? (
                        <div className="flex flex-col space-y-2 animate-in slide-in-from-right-4 duration-300">
                           <button 
                             onClick={(e) => confirmDelete(entry.id, e)}
                             className="bg-red-500 text-white p-2 rounded-xl active:scale-90 transition-transform shadow-lg shadow-red-500/20"
                           >
                             <span className="material-icons-round text-lg">check</span>
                           </button>
                           <button 
                             onClick={cancelDelete}
                             className="bg-white/10 text-slate-400 p-2 rounded-xl active:scale-90 transition-transform"
                           >
                             <span className="material-icons-round text-lg">close</span>
                           </button>
                        </div>
                      ) : (
                        <button 
                          onClick={(e) => initiateDelete(entry.id, e)}
                          className="opacity-0 group-hover:opacity-100 p-2 text-slate-600 hover:text-red-500 transition-all active:scale-90"
                        >
                          <span className="material-icons-round">delete_outline</span>
                        </button>
                      )}
                    </div>

                    {/* Simple animated background for confirmation */}
                    {confirmDeleteId === entry.id && (
                      <div className="absolute inset-0 bg-red-500/5 animate-pulse"></div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}

        {weeklyHistory.length === 0 && searchQuery && (
          <div className="py-20 flex flex-col items-center text-center space-y-6 opacity-30">
            <div className="w-20 h-20 rounded-full bg-white/5 flex items-center justify-center">
              <span className="material-icons-round text-5xl">search_off</span>
            </div>
            <p className="text-sm font-medium px-12 leading-relaxed">
              Nothing found matching "{searchQuery}" in the last 7 days.
            </p>
          </div>
        )}
      </section>

      <div className="pb-10"></div>
    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { NutritionData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Uses Gemini-3-Flash to analyze food images.
 * Optimized for accurate portion estimation and macro calculation.
 */
export const analyzeFoodImage = async (base64Image: string): Promise<NutritionData> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image,
          },
        },
        {
          text: `You are a professional nutritionist and food vision expert. 
          Perform a detailed analysis of this food image:
          1. DISH IDENTIFICATION: Name the dish accurately (e.g., "Paneer Butter Masala with 2 Butter Naan").
          2. PORTION ESTIMATION: Look at the plate, cutlery, or container for scale. Estimate the actual amount present in the image (e.g., "approx. 250g of curry and 2 large flatbreads"). Be specific about count, volume, or weight.
          3. MACRO CALCULATION: Calculate the nutritional values based EXCLUSIVELY on the portion size estimated in step 2, not a generic 100g serving.
          4. CULTURAL CONTEXT: If it's Indian or ethnic food, account for common cooking oils (ghee/oil) and specific ingredient densities.

          Return ONLY a JSON object matching the requested schema.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { 
            type: Type.STRING,
            description: "The name of the dish identified."
          },
          calories: { 
            type: Type.NUMBER,
            description: "Total calories for the portion shown."
          },
          protein: { 
            type: Type.NUMBER,
            description: "Protein in grams for the portion shown."
          },
          carbs: { 
            type: Type.NUMBER,
            description: "Carbohydrates in grams for the portion shown."
          },
          fats: { 
            type: Type.NUMBER,
            description: "Fats in grams for the portion shown."
          },
          fiber: { 
            type: Type.NUMBER,
            description: "Dietary fiber in grams for the portion shown."
          },
          portionDescription: { 
            type: Type.STRING,
            description: "A detailed description of the portion size estimated from the image (e.g., '1 large bowl (approx 400ml)', '3 medium pieces', '250g portion')."
          },
        },
        required: ["foodName", "calories", "protein", "carbs", "fats", "fiber", "portionDescription"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");

  try {
    return JSON.parse(text) as NutritionData;
  } catch (e) {
    console.error("Failed to parse AI response:", text);
    throw new Error("Invalid response format from AI");
  }
};

/**
 * Generates 3 recipe suggestions tailored to a specific fitness goal.
 */
export const generateRecipes = async (goal: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Suggest 3 unique, healthy recipes specifically for someone with the fitness goal: ${goal}. 
    Focus on ingredients that are easy to find and preparation methods that are relatively quick.
    Provide nutritional estimates for a standard single serving.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
            calories: { type: Type.NUMBER },
            protein: { type: Type.NUMBER },
            carbs: { type: Type.NUMBER },
            fats: { type: Type.NUMBER },
          },
          required: ["title", "description", "ingredients", "calories", "protein", "carbs", "fats"]
        }
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No recipes found");
  return JSON.parse(text);
};

