import React, { useMemo } from 'react';
import { FoodEntry, UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  entries: FoodEntry[];
  waterGlasses: number;
  setWaterGlasses: (val: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, entries, waterGlasses, setWaterGlasses }) => {
  const consumed = entries.reduce((acc, entry) => acc + entry.calories, 0);
  const isSurplus = consumed > user.dailyCalorieGoal;
  const isGoalReached = consumed >= user.dailyCalorieGoal * 0.9 && consumed <= user.dailyCalorieGoal;
  const remaining = Math.max(0, user.dailyCalorieGoal - consumed);
  const surplus = isSurplus ? consumed - user.dailyCalorieGoal : 0;

  const progressPercent = Math.min(100, (consumed / user.dailyCalorieGoal) * 100);

  const totalMacros = useMemo(() => entries.reduce((acc, e) => ({
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
    fi: acc.fi + (e.fiber || 0),
  }), { p: 0, c: 0, f: 0, fi: 0 }), [entries]);

  const stepProgress = Math.min(100, (user.currentSteps / user.dailyStepGoal) * 100);

  const getSuggestions = () => {
    const tips = [];
    const proteinDeficit = user.macros.protein - totalMacros.p;
    if (proteinDeficit > 20) {
      tips.push({
        icon: 'egg',
        text: `You need ${Math.round(proteinDeficit)}g more protein. Try a Greek yogurt or some paneer.`,
        color: 'text-primary'
      });
    }
    const fiberDeficit = user.macros.fiber - totalMacros.fi;
    if (fiberDeficit > 10) {
      tips.push({
        icon: 'eco',
        text: `Fiber check: Adding flax seeds or an apple will help digestion today.`,
        color: 'text-green-400'
      });
    }
    if (consumed > user.dailyCalorieGoal * 0.9 && !isSurplus) {
      tips.push({
        icon: 'verified',
        text: `Calorie precision! You are perfectly hitting your target for ${user.goal}.`,
        color: 'text-primary'
      });
    }
    if (waterGlasses < (user.dailyWaterGoal || 10) * 0.5) {
      tips.push({
        icon: 'water_drop',
        text: `Metabolism needs water. Drink more to reach your hydration goal.`,
        color: 'text-blue-400'
      });
    }
    return tips.length > 0 ? tips : [{ icon: 'verified', text: `Spot on! You are executing your plan flawlessly.`, color: 'text-primary' }];
  };

  const suggestions = useMemo(() => getSuggestions(), [totalMacros, consumed, waterGlasses, user]);

  const mainSize = 200;
  const mainCenter = mainSize / 2;
  const mainRadius = 85;
  const mainCircumference = 2 * Math.PI * mainRadius;
  const mainOffset = mainCircumference - (progressPercent / 100) * mainCircumference;

  const MacroCard = ({ 
    label, 
    current, 
    goal, 
    color, 
    icon 
  }: { 
    label: string, 
    current: number, 
    goal: number, 
    color: string, 
    icon: string 
  }) => {
    const macroPercent = Math.min(100, (current / goal) * 100);
    const smallSize = 80;
    const smallCenter = smallSize / 2;
    const smallRadius = 32;
    const smallCircumference = 2 * Math.PI * smallRadius;
    const smallOffset = smallCircumference - (macroPercent / 100) * smallCircumference;

    return (
      <div className="glass-card rounded-[2rem] p-6 flex flex-col items-center border border-white/5 transition-all hover:bg-white/[0.08] duration-300 group animate-in zoom-in-95 duration-500">
        {/* Arc Progress */}
        <div className="relative w-16 h-16 mb-6">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${smallSize} ${smallSize}`}>
            <circle 
              className="text-white/[0.03]" 
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeWidth="6" 
            />
            <circle 
              className={`${color}`}
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeDasharray={smallCircumference} 
              strokeDashoffset={smallOffset} 
              strokeLinecap="round" 
              strokeWidth="6" 
              style={{ transition: 'stroke-dashoffset 1.5s cubic-bezier(0.4, 0, 0.2, 1)' }} 
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className={`material-icons-round text-lg ${color} group-hover:scale-110 transition-transform duration-500`}>{icon}</span>
          </div>
        </div>

        {/* Label & Value */}
        <div className="text-center w-full space-y-1">
          <p className="text-[10px] font-black uppercase tracking-[0.3em] text-white/30 mb-2">{label}</p>
          <div className="flex items-baseline justify-center space-x-1 mb-4">
            <p className="text-lg font-black text-white">{Math.round(current)}g</p>
            <p className="text-[10px] font-black text-white/20">/ {goal}g</p>
          </div>

          {/* Horizontal Bar */}
          <div className="w-full h-[3px] bg-white/5 rounded-full overflow-hidden mb-2">
            <div 
              className={`h-full ${color.replace('text-', 'bg-')} rounded-full transition-all duration-1000`} 
              style={{ width: `${macroPercent}%` }}
            ></div>
          </div>

          {/* Reached Text */}
          <div className="flex items-center justify-center space-x-1">
             <div className={`w-1 h-1 rounded-full ${color.replace('text-', 'bg-')} opacity-40`}></div>
             <p className="text-[7px] font-black text-slate-600 uppercase tracking-[0.25em]">{Math.round(macroPercent)}% reached</p>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 pb-10">
      <header className="flex justify-between items-center px-1">
        <div>
          <p className="text-[10px] font-black text-primary uppercase tracking-[0.25em] mb-1 opacity-70">
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
          </p>
          <h1 className="text-2xl font-black tracking-tight text-white">Hey, {user.name.split(' ')[0]}!</h1>
        </div>
        <div className="w-11 h-11 rounded-xl bg-white/5 border border-white/5 p-1">
          <img src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="Avatar" className="w-full h-full rounded-lg object-cover" />
        </div>
      </header>

      {/* Main Calorie Ring */}
      <section className="glass-card rounded-[2.5rem] p-8 flex flex-col items-center justify-center relative overflow-hidden border border-white/5 animate-in fade-in duration-700">
        <div className="relative w-56 h-56 flex items-center justify-center">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${mainSize} ${mainSize}`}>
            <circle className="text-white/[0.02]" cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeWidth="12" />
            <circle className={isSurplus ? "text-red-500" : "text-primary"} cx={mainCenter} cy={mainCenter} fill="transparent" r={mainRadius} stroke="currentColor" strokeDasharray={mainCircumference} strokeDashoffset={mainOffset} strokeLinecap="round" strokeWidth="12" style={{ transition: 'stroke-dashoffset 1.2s cubic-bezier(0.4, 0, 0.2, 1)' }} />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
            <span className="text-5xl font-black text-white tabular-nums tracking-tighter">{isSurplus ? `+${surplus}` : remaining.toLocaleString()}</span>
            <span className="text-[10px] text-white/40 font-black uppercase tracking-[0.3em] mt-2">{isSurplus ? 'Surplus' : 'kcal left'}</span>
          </div>
        </div>
      </section>

      {/* Macro Grid */}
      <section className="grid grid-cols-2 gap-4">
        <MacroCard label="Protein" current={totalMacros.p} goal={user.macros.protein} icon="egg" color="text-emerald-400" />
        <MacroCard label="Carbs" current={totalMacros.c} goal={user.macros.carbs} icon="grain" color="text-amber-400" />
        <MacroCard label="Fats" current={totalMacros.f} goal={user.macros.fats} icon="opacity" color="text-orange-400" />
        <MacroCard label="Fiber" current={totalMacros.fi} goal={user.macros.fiber} icon="eco" color="text-lime-400" />
      </section>

      {/* Steps and Hydration - Screenshot Match */}
      <section className="grid grid-cols-2 gap-4">
        {/* Steps Card */}
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group min-h-[140px] flex flex-col justify-between hover:bg-white/[0.05] transition-all">
          <div className="flex items-center space-x-3 relative z-10">
             <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center shadow-lg shadow-primary/20">
               <span className="material-icons-round text-black text-lg">directions_run</span>
             </div>
             <span className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Steps</span>
          </div>

          <div className="absolute right-[-10px] bottom-[10px] opacity-[0.03] group-hover:scale-110 transition-transform duration-1000 pointer-events-none">
             <span className="material-icons-round text-7xl">directions_run</span>
          </div>

          <div className="mt-6 relative z-10">
            <div className="flex items-baseline space-x-1.5 mb-3">
              <p className="text-xl font-black text-white">{user.currentSteps.toLocaleString()}</p>
              <p className="text-[10px] font-black text-white/20 uppercase tracking-[0.1em]">/ {user.dailyStepGoal.toLocaleString()}</p>
            </div>
            <div className="w-full h-[6px] bg-white/5 rounded-full overflow-hidden">
              <div 
                className="h-full bg-primary rounded-full transition-all duration-1000 shadow-[0_0_8px_rgba(19,236,55,0.4)]" 
                style={{ width: `${stepProgress}%` }}
              ></div>
            </div>
          </div>
        </div>

        {/* Hydration Card */}
        <div 
          className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group min-h-[140px] flex flex-col justify-between hover:bg-white/[0.05] transition-all cursor-pointer" 
          onClick={() => setWaterGlasses(waterGlasses + 1)}
        >
          <div className="flex items-center justify-between relative z-10">
            <div className="flex items-center space-x-3">
               <div className="w-8 h-8 bg-blue-500/20 rounded-full flex items-center justify-center">
                 <span className="material-icons-round text-blue-400 text-lg">water_drop</span>
               </div>
               <span className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Hydration</span>
            </div>

            <button 
              onClick={(e) => {
                e.stopPropagation();
                setWaterGlasses(Math.max(0, waterGlasses - 1));
              }}
              className="w-6 h-6 rounded-lg bg-white/5 flex items-center justify-center text-white/30 hover:text-white transition-all active:scale-90"
