import React, { useMemo } from 'react';
import { FoodEntry, UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  entries: FoodEntry[];
  waterGlasses: number;
  setWaterGlasses: (val: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, entries, waterGlasses, setWaterGlasses }) => {
  const consumed = entries.reduce((acc, entry) => acc + entry.calories, 0);
  const isSurplus = consumed > user.dailyCalorieGoal;
  const remaining = Math.max(0, user.dailyCalorieGoal - consumed);
  const surplus = isSurplus ? consumed - user.dailyCalorieGoal : 0;
  const progressPercent = Math.min(100, (consumed / user.dailyCalorieGoal) * 100);

  const totalMacros = useMemo(() => entries.reduce((acc, e) => ({
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
    fi: acc.fi + (e.fiber || 0),
  }), { p: 0, c: 0, f: 0, fi: 0 }), [entries]);

  const stepProgress = Math.min(100, (user.currentSteps / user.dailyStepGoal) * 100);

  const mainSize = 220;
  const mainCenter = mainSize / 2;
  const mainRadius = 90;
  const mainCircumference = 2 * Math.PI * mainRadius;
  const mainOffset = mainCircumference - (progressPercent / 100) * mainCircumference;

  const MacroCard = ({ label, current, goal, color, icon }: any) => {
    const macroPercent = Math.min(100, (current / goal) * 100);
    const size = 80;
    const center = size / 2;
    const radius = 32;
    const circ = 2 * Math.PI * radius;
    const offset = circ - (macroPercent / 100) * circ;

    return (
      <div className="glass-card rounded-[2.2rem] p-6 flex flex-col items-center border border-white/5 transition-all hover:bg-white/[0.06] duration-300 group animate-in zoom-in-95">
        <div className="relative w-16 h-16 mb-5">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${size} ${size}`}>
            <circle cx={center} cy={center} r={radius} fill="transparent" stroke="rgba(255,255,255,0.03)" strokeWidth="6" />
            <circle cx={center} cy={center} r={radius} fill="transparent" stroke="currentColor" strokeWidth="6" strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round" className={`${color} transition-all duration-1000`} />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className={`material-icons-round text-lg ${color} opacity-80`}>{icon}</span>
          </div>
        </div>
        <div className="text-center w-full">
          <p className="text-[10px] font-black uppercase tracking-[0.3em] text-white/20 mb-2">{label}</p>
          <div className="flex items-baseline justify-center space-x-1 mb-4">
            <p className="text-xl font-black text-white">{Math.round(current)}<span className="text-[10px] opacity-40 ml-0.5">g</span></p>
            <p className="text-[10px] font-black text-white/10 italic">/ {goal}g</p>
          </div>
          <div className="w-full h-[3px] bg-white/5 rounded-full overflow-hidden mb-2.5">
            <div className={`h-full ${color.replace('text-', 'bg-')} rounded-full transition-all duration-1000`} style={{ width: `${macroPercent}%` }}></div>
          </div>
          <div className="flex items-center justify-center space-x-1.5">
             <div className={`w-1 h-1 rounded-full ${color.replace('text-', 'bg-')} shadow-[0_0_8px_currentColor]`}></div>
             <p className="text-[7px] font-black text-slate-600 uppercase tracking-[0.2em]">{Math.round(macroPercent)}% reached</p>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 pb-20 view-enter">
      <header className="flex justify-between items-center px-1">
        <div>
          <p className="text-[10px] font-black text-primary uppercase tracking-[0.3em] mb-1 opacity-60">
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
          </p>
          <h1 className="text-2xl font-black tracking-tight text-white">Hey, {user.name.split(' ')[0]}!</h1>
        </div>
        <div className="w-12 h-12 rounded-2xl bg-white/5 border border-white/5 p-1 transition-transform active:scale-95">
          <img src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="Avatar" className="w-full h-full rounded-[14px] object-cover" />
        </div>
      </header>

      {/* Hero Calorie Progress */}
      <section className="glass-card rounded-[2.5rem] p-10 flex flex-col items-center justify-center relative border border-white/5 animate-in fade-in duration-700">
        <div className="relative w-64 h-64 flex items-center justify-center">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${mainSize} ${mainSize}`}>
            <circle cx={mainCenter} cy={mainCenter} r={mainRadius} fill="transparent" stroke="rgba(255,255,255,0.02)" strokeWidth="14" />
            <circle cx={mainCenter} cy={mainCenter} r={mainRadius} fill="transparent" stroke="currentColor" strokeWidth="14" strokeDasharray={mainCircumference} strokeDashoffset={mainOffset} strokeLinecap="round" className={isSurplus ? "text-red-500" : "text-primary"} style={{ transition: 'stroke-dashoffset 1.2s ease-out' }} />
