      <section className="grid grid-cols-2 gap-4">
        {/* Steps */}
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group min-h-[150px] flex flex-col justify-between hover:bg-white/[0.05] transition-all duration-300">
          <div className="flex items-center space-x-3 relative z-10">
             <div className="w-9 h-9 bg-primary rounded-full flex items-center justify-center shadow-lg shadow-primary/20">
               <span className="material-icons-round text-black text-lg font-bold">directions_run</span>
             </div>
             <span className="text-[10px] font-black text-white uppercase tracking-[0.3em] opacity-50">Steps</span>
          </div>
          <div className="mt-6 relative z-10">
            <div className="flex items-baseline space-x-1.5 mb-3">
              <p className="text-2xl font-black text-white">{user.currentSteps.toLocaleString()}</p>
              <p className="text-[10px] font-black text-white/10 uppercase">/ {user.dailyStepGoal.toLocaleString()}</p>
