        </div>

        {/* Hydration */}
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 relative overflow-hidden group min-h-[150px] flex flex-col justify-between hover:bg-white/[0.05] transition-all cursor-pointer" onClick={() => setWaterGlasses(waterGlasses + 1)}>
          <div className="flex items-center justify-between relative z-10">
            <div className="flex items-center space-x-3">
               <div className="w-9 h-9 bg-blue-500/20 rounded-full flex items-center justify-center">
                 <span className="material-icons-round text-blue-400 text-lg">water_drop</span>
               </div>
               <span className="text-[10px] font-black text-white uppercase tracking-[0.3em] opacity-50">Hydration</span>
            </div>
            <button 
              onClick={(e) => { e.stopPropagation(); setWaterGlasses(Math.max(0, waterGlasses - 1)); }}
