            <div className="flex gap-1.5 h-1.5">
              {Array.from({ length: user.dailyWaterGoal || 10 }).map((_, i) => (
                <div key={i} className={`flex-1 rounded-full transition-all duration-300 ${i < waterGlasses ? 'bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,0.5)]' : 'bg-white/5'}`} />
