  'https://api.dicebear.com/7.x/avataaars/svg?seed=Buddy',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Cookie',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Milo',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Lilly',
];

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isRemindersOpen, setIsRemindersOpen] = useState(false);
  const [isEditingCalories, setIsEditingCalories] = useState(false);
  const [isEditingSteps, setIsEditingSteps] = useState(false);
  const [isEditingWater, setIsEditingWater] = useState(false);

  const [isEditingProtein, setIsEditingProtein] = useState(false);
  const [isEditingCarbs, setIsEditingCarbs] = useState(false);
  const [isEditingFats, setIsEditingFats] = useState(false);
  const [isEditingFiber, setIsEditingFiber] = useState(false);

  const [tempCalories, setTempCalories] = useState(user.dailyCalorieGoal);
  const [tempSteps, setTempSteps] = useState(user.dailyStepGoal);
  const [tempWater, setTempWater] = useState(user.dailyWaterGoal || 10);

  const [tempProtein, setTempProtein] = useState(user.macros.protein);
  const [tempCarbs, setTempCarbs] = useState(user.macros.carbs);
  const [tempFats, setTempFats] = useState(user.macros.fats);
  const [tempFiber, setTempFiber] = useState(user.macros.fiber);

  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isIncomplete = !user.dailyCalorieGoal || !user.dailyStepGoal || !user.weight || !user.targetWeight || !user.dailyWaterGoal;

  const goals = [
    { id: 'Cut', icon: 'trending_down', label: 'Lose Weight', desc: 'Calorie deficit' },
    { id: 'Maintain', icon: 'trending_flat', label: 'Stay Fit', desc: 'Equal intake' },
    { id: 'Bulk', icon: 'trending_up', label: 'Build Muscle', desc: 'Calorie surplus' },
  ];

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      if (!file.type.startsWith('image/')) {
        setUploadError('Please select a valid image file (PNG, JPG, etc.)');
        return;
      }
      if (file.size > MAX_FILE_SIZE) {
        setUploadError('Image is too large. Please select a file under 5MB.');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ avatarUrl: reader.result as string });
        setIsModalOpen(false);
      };
      reader.onerror = () => {
        setUploadError('Error reading file. Please try again.');
      };
      reader.readAsDataURL(file);
    }
  };

  const selectPreset = (url: string) => {
    setUploadError(null);
    onUpdate({ avatarUrl: url });
    setIsModalOpen(false);
  };

  const generateNewDiceBear = () => {
    setUploadError(null);
    const randomSeed = Math.random().toString(36).substring(7);
    onUpdate({ avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=${randomSeed}` });
    setIsModalOpen(false);
  };

  const handleSaveCalories = () => {
    onUpdate({ dailyCalorieGoal: tempCalories });
    setIsEditingCalories(false);
  };

  const handleSaveSteps = () => {
    onUpdate({ dailyStepGoal: tempSteps });
    setIsEditingSteps(false);
  };

  const handleSaveWater = () => {
    onUpdate({ dailyWaterGoal: tempWater });
    setIsEditingWater(false);
  };

  const handleSaveProtein = () => {
    onUpdate({ macros: { ...user.macros, protein: tempProtein } });
    setIsEditingProtein(false);
  };

  const handleSaveCarbs = () => {
    onUpdate({ macros: { ...user.macros, carbs: tempCarbs } });
    setIsEditingCarbs(false);
  };

  const handleSaveFats = () => {
    onUpdate({ macros: { ...user.macros, fats: tempFats } });
    setIsEditingFats(false);
  };

  const handleSaveFiber = () => {
    onUpdate({ macros: { ...user.macros, fiber: tempFiber } });
    setIsEditingFiber(false);
  };

  const openModal = () => {
    setUploadError(null);
    setIsModalOpen(true);
  };

  // Reminders Logic
  const toggleReminder = (id: string) => {
    const updated = (user.reminders || []).map(r => 
      r.id === id ? { ...r, enabled: !r.enabled } : r
    );
    onUpdate({ reminders: updated });
  };

  const addReminder = (type: Reminder['type']) => {
    const newReminder: Reminder = {
      id: `rem-${Date.now()}`,
      type,
      time: '09:00',
      enabled: true
    };
    onUpdate({ reminders: [...(user.reminders || []), newReminder] });
  };

  const deleteReminder = (id: string) => {
    const updated = (user.reminders || []).filter(r => r.id !== id);
    onUpdate({ reminders: updated });
  };

  const updateReminderTime = (id: string, time: string) => {
    const updated = (user.reminders || []).map(r => 
      r.id === id ? { ...r, time } : r
    );
    onUpdate({ reminders: updated });
  };

  const MacroEditRow = ({ 
    label, 
    value, 
    tempValue, 
    setTempValue, 
    isEditing, 
    setIsEditing, 
    onSave, 
    unit = 'g', 
    colorClass = 'text-primary' 
  }: any) => (
    <div className="flex justify-between items-start pt-6 border-t border-white/5">
      <div 
        className="cursor-pointer group flex-1"
        onClick={() => {
          if (!isEditing) {
            setTempValue(value);
            setIsEditing(true);
          }
        }}
      >
        <p className={`text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:${colorClass} transition-colors`}>{label}</p>
        {isEditing ? (
          <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
            <input 
              type="number"
              value={tempValue}
              autoFocus
              onChange={(e) => setTempValue(Number(e.target.value))}
              className={`bg-white/5 border border-white/10 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:${colorClass.replace('text-', 'ring-')} text-white`}
            />
            <button 
              onClick={onSave}
              className={`w-8 h-8 rounded-lg ${colorClass.replace('text-', 'bg-')} text-black flex items-center justify-center active:scale-90`}
            >
              <span className="material-icons-round text-sm">check</span>
            </button>
          </div>
        ) : (
          <p className={`text-xl font-black group-hover:${colorClass} transition-colors`}>
            {value || 0} <span className="text-xs font-medium text-slate-500 ml-1">{unit}</span>
          </p>
        )}
      </div>
      {!isEditing && (
        <button 
          onClick={() => {
            setTempValue(value);
            setIsEditing(true);
          }}
          className={`${colorClass} text-xs font-black uppercase tracking-widest ${colorClass.replace('text-', 'bg-')}/10 px-4 py-2 rounded-xl active:scale-95 transition-all`}
        >
          Adjust
        </button>
      )}
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col items-center text-center">
        <div className="relative group mb-4">
           <div className="absolute -inset-1 bg-gradient-to-tr from-primary to-primary/20 rounded-[2rem] blur opacity-25 group-hover:opacity-50 transition duration-500"></div>
           <div className="relative w-28 h-28 rounded-[2rem] bg-background-dark border-2 border-white/5 p-1 shadow-2xl overflow-hidden">
              <img 
                src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} 
                alt="Profile" 
                className="w-full h-full rounded-[1.8rem] bg-surface-dark object-cover" 
              />
              <button 
                onClick={openModal}
                className="absolute -bottom-2 -right-2 w-10 h-10 bg-primary rounded-2xl flex items-center justify-center text-black shadow-lg border-4 border-background-dark active:scale-90 transition-transform"
              >
                <span className="material-icons-round text-xl">camera_alt</span>
              </button>
           </div>
        </div>
        <h1 className="text-2xl font-black tracking-tight">{user.name}</h1>
        <p className="text-sm text-slate-500 font-medium">NutriVision Free Plan</p>
      </header>

      {/* Completion Prompt */}
      {isIncomplete && (
        <div className="bg-primary/10 border border-primary/20 rounded-[2rem] p-5 flex items-center gap-4 animate-in fade-in slide-in-from-top-4 duration-700 mx-1">
          <div className="w-12 h-12 rounded-2xl bg-primary/20 flex items-center justify-center text-primary shrink-0">
            <span className="material-icons-round text-2xl">priority_high</span>
          </div>
          <div className="flex-1">
            <p className="text-[11px] font-black text-primary uppercase tracking-[0.15em]">Setup Incomplete</p>
            <p className="text-[10px] text-white/60 font-bold leading-relaxed mt-1">
              Add your targets and weight below. Complete data allows the AI to give you 100% accurate macro scores.
            </p>
          </div>
        </div>
      )}

      {/* Avatar Customization Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass-card w-full max-sm rounded-[2.5rem] p-6 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden relative">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-black tracking-tight text-white">Choose Avatar</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-white/40 hover:text-white transition-colors">
                <span className="material-icons-round text-lg">close</span>
              </button>
            </div>

            <div className="space-y-6">
              {uploadError && (
                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 animate-in shake duration-300">
                  <span className="material-icons-round text-red-400 text-sm">error_outline</span>
                  <p className="text-[10px] font-bold text-red-400 uppercase tracking-wider">{uploadError}</p>
                </div>
              )}

              <button 
                onClick={() => fileInputRef.current?.click()}
                className={`w-full flex items-center p-4 bg-primary/10 border border-primary/20 rounded-2xl group active:scale-[0.98] transition-all ${uploadError ? 'ring-1 ring-red-500/50' : ''}`}
              >
                <div className="w-10 h-10 rounded-xl bg-primary text-black flex items-center justify-center mr-4">
                  <span className="material-icons-round">upload</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-primary uppercase tracking-wider">Upload Photo</p>
                  <p className="text-[10px] text-slate-500 font-bold">Select from your gallery (Max 5MB)</p>
                </div>
                <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
              </button>

              <div className="space-y-3">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Premium Presets</p>
                <div className="grid grid-cols-4 gap-3">
                  {PRESET_AVATARS.map((url, i) => (
                    <button 
                      key={i} 
                      onClick={() => selectPreset(url)}
                      className={`aspect-square rounded-xl bg-white/5 border-2 transition-all active:scale-90 ${user.avatarUrl === url ? 'border-primary' : 'border-transparent hover:border-white/10'}`}
                    >
                      <img src={url} alt={`Preset ${i}`} className="w-full h-full p-1" />
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={generateNewDiceBear}
                className="w-full flex items-center p-4 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors group"
              >
                <div className="w-10 h-10 rounded-xl bg-white/10 text-white/60 flex items-center justify-center mr-4 group-hover:text-primary transition-colors">
                  <span className="material-icons-round">casino</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-white/80 uppercase tracking-wider">Surprise Me</p>
                  <p className="text-[10px] text-slate-500 font-bold">Generate a random character</p>
                </div>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Reminders Modal */}
      {isRemindersOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass-card w-full max-w-[400px] rounded-[2.5rem] p-7 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden relative flex flex-col max-h-[85vh]">
            <div className="flex justify-between items-center mb-6 shrink-0">
              <div>
                <h3 className="text-lg font-black tracking-tight text-white">Notifications</h3>
                <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mt-0.5">Stay on track</p>
              </div>
              <button onClick={() => setIsRemindersOpen(false)} className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-white/40 hover:text-white transition-colors">
                <span className="material-icons-round">close</span>
              </button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-4 pb-4">
              {(user.reminders || []).length === 0 ? (
                <div className="py-12 text-center space-y-3 opacity-30">
                  <span className="material-icons-round text-5xl">notifications_off</span>
                  <p className="text-xs font-bold uppercase tracking-widest leading-loose">No active reminders</p>
                </div>
              ) : (
                (user.reminders || []).map((rem) => (
                  <div key={rem.id} className="bg-white/5 border border-white/5 rounded-2xl p-4 flex items-center justify-between group transition-all hover:bg-white/[0.08]">
                    <div className="flex items-center space-x-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                        rem.type === 'Meal' ? 'bg-orange-500/10 text-orange-400' :
                        rem.type === 'Water' ? 'bg-blue-500/10 text-blue-400' :
                        'bg-primary/10 text-primary'
                      }`}>
                        <span className="material-icons-round text-xl">
                          {rem.type === 'Meal' ? 'restaurant' : rem.type === 'Water' ? 'water_drop' : 'directions_run'}
                        </span>
                      </div>
                      <div>
                        <p className="text-xs font-black text-white/80">{rem.type} Reminder</p>
                        <input 
                          type="time" 
                          value={rem.time}
                          onChange={(e) => updateReminderTime(rem.id, e.target.value)}
                          className="bg-transparent border-none text-[10px] font-black text-slate-500 focus:ring-0 p-0 hover:text-primary transition-colors cursor-pointer uppercase"
                        />
                      </div>
                    </div>

                    <div className="flex items-center space-x-3">
                      <button 
                        onClick={() => toggleReminder(rem.id)}
                        className={`w-12 h-6 rounded-full transition-all duration-300 p-1 flex items-center ${rem.enabled ? 'bg-primary' : 'bg-white/10'}`}
                      >
                        <div className={`w-4 h-4 rounded-full bg-white transition-all shadow-md ${rem.enabled ? 'translate-x-6' : 'translate-x-0'}`}></div>
                      </button>
                      <button 
                        onClick={() => deleteReminder(rem.id)}
                        className="opacity-0 group-hover:opacity-100 p-2 text-slate-600 hover:text-red-500 transition-all"
                      >
                        <span className="material-icons-round text-lg">delete</span>
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="pt-6 border-t border-white/5 space-y-3 shrink-0">
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest px-1">Add New Alert</p>
              <div className="grid grid-cols-3 gap-2">
                {[
                  { type: 'Meal', icon: 'lunch_dining', color: 'text-orange-400' },
                  { type: 'Water', icon: 'water_drop', color: 'text-blue-400' },
                  { type: 'Steps', icon: 'directions_walk', color: 'text-primary' },
                ].map((item) => (
                  <button 
                    key={item.type}
                    onClick={() => addReminder(item.type as any)}
                    className="bg-white/5 hover:bg-white/10 border border-white/5 py-3 rounded-xl flex flex-col items-center space-y-1 transition-all active:scale-95"
                  >
                    <span className={`material-icons-round text-sm ${item.color}`}>{item.icon}</span>
                    <span className="text-[8px] font-black uppercase text-slate-400">{item.type}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Active Goal</h2>
        <div className="grid grid-cols-1 gap-3">
          {goals.map((g) => (
            <button
              key={g.id}
              onClick={() => onUpdate({ goal: g.id as any })}
              className={`flex items-center p-4 rounded-3xl border transition-all ${
                user.goal === g.id 
                  ? 'bg-primary/10 border-primary shadow-[0_0_20px_rgba(19,236,55,0.1)]' 
                  : 'bg-white/5 border-white/5 hover:border-white/10'
              }`}
            >
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 ${user.goal === g.id ? 'bg-primary text-black' : 'bg-white/5 text-slate-500'}`}>
                <span className="material-icons-round text-2xl">{g.icon}</span>
              </div>
              <div className="text-left flex-1">
                <p className={`font-black tracking-tight ${user.goal === g.id ? 'text-primary' : 'text-white'}`}>{g.label}</p>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{g.desc}</p>
              </div>
              {user.goal === g.id && (
                <span className="material-icons-round text-primary">check_circle</span>
              )}
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Daily Targets</h2>
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 space-y-6">
          <div className="flex justify-between items-start">
            <div 
              className="cursor-pointer group" 
              onClick={() => {
                if (!isEditingCalories) {
                  setTempCalories(user.dailyCalorieGoal);
                  setIsEditingCalories(true);
                }
              }}
            >
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-primary transition-colors">Calories</p>
              {isEditingCalories ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input 
                    type="number"
                    value={tempCalories}
                    autoFocus
                    onChange={(e) => setTempCalories(Number(e.target.value))}
                    className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white"
                  />
                  <button 
                    onClick={handleSaveCalories}
                    className="w-8 h-8 rounded-lg bg-primary text-black flex items-center justify-center active:scale-90"
                  >
                    <span className="material-icons-round text-sm">check</span>
                  </button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-primary transition-colors">
                  {user.dailyCalorieGoal || 0} <span className="text-xs font-medium text-slate-500 ml-1">kcal</span>
                </p>
              )}
            </div>
            {!isEditingCalories && (
              <button 
                onClick={() => {
                  setTempCalories(user.dailyCalorieGoal);
                  setIsEditingCalories(true);
                }}
                className="text-primary text-xs font-black uppercase tracking-widest bg-primary/10 px-4 py-2 rounded-xl active:scale-95 transition-all"
              >
                Adjust
              </button>
            )}
          </div>

          <div className="flex justify-between items-start pt-6 border-t border-white/5">
            <div 
              className="cursor-pointer group"
              onClick={() => {
                if (!isEditingSteps) {
                  setTempSteps(user.dailyStepGoal);
                  setIsEditingSteps(true);
                }
              }}
            >
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-primary transition-colors">Step Goal</p>
              {isEditingSteps ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input 
                    type="number"
                    value={tempSteps}
                    autoFocus
                    onChange={(e) => setTempSteps(Number(e.target.value))}
                    className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white"
                  />
                  <button 
                    onClick={handleSaveSteps}
                    className="w-8 h-8 rounded-lg bg-primary text-black flex items-center justify-center active:scale-90"
                  >
                    <span className="material-icons-round text-sm">check</span>
                  </button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-primary transition-colors">
                  {user.dailyStepGoal || 0} <span className="text-xs font-medium text-slate-500 ml-1">steps</span>
                </p>
              )}
            </div>
            {!isEditingSteps && (
              <button 
                onClick={() => {
                  setTempSteps(user.dailyStepGoal);
                  setIsEditingSteps(true);
                }}
                className="text-primary text-xs font-black uppercase tracking-widest bg-primary/10 px-4 py-2 rounded-xl active:scale-95 transition-all"
              >
                Adjust
              </button>
            )}
          </div>

          <div className="flex justify-between items-start pt-6 border-t border-white/5">
            <div 
              className="cursor-pointer group"
              onClick={() => {
                if (!isEditingWater) {
                  setTempWater(user.dailyWaterGoal || 10);
                  setIsEditingWater(true);
                }
              }}
            >
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-blue-400 transition-colors">Water Goal</p>
              {isEditingWater ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input 
                    type="number"
                    value={tempWater}
                    autoFocus
                    onChange={(e) => setTempWater(Number(e.target.value))}
                    className="bg-white/5 border border-blue-400/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-blue-400 text-white"
                  />
                  <button 
                    onClick={handleSaveWater}
                    className="w-8 h-8 rounded-lg bg-blue-400 text-white flex items-center justify-center active:scale-90"
                  >
                    <span className="material-icons-round text-sm">check</span>
                  </button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-blue-400 transition-colors">
                  {user.dailyWaterGoal || 10} <span className="text-xs font-medium text-slate-500 ml-1">glasses</span>
                </p>
              )}
            </div>
            {!isEditingWater && (
              <button 
                onClick={() => {
                  setTempWater(user.dailyWaterGoal || 10);
                  setIsEditingWater(true);
                }}
                className="text-blue-400 text-xs font-black uppercase tracking-widest bg-blue-400/10 px-4 py-2 rounded-xl active:scale-95 transition-all"
              >
                Adjust
              </button>
            )}
          </div>

          {/* Macro Targets */}
          <MacroEditRow 
            label="Protein Target" 
            value={user.macros.protein} 
            tempValue={tempProtein} 
            setTempValue={setTempProtein} 
            isEditing={isEditingProtein} 
