              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 ${user.goal === g.id ? 'bg-primary text-black' : 'bg-white/5 text-slate-500'}`}><span className="material-icons-round text-2xl">{g.icon}</span></div>
              <div className="text-left flex-1"><p className={`font-black tracking-tight ${user.goal === g.id ? 'text-primary' : 'text-white'}`}>{g.label}</p><p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{g.desc}</p></div>
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Daily Targets</h2>
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 space-y-6">
          <MacroEditRow label="Calories" value={user.dailyCalorieGoal} tempValue={tempCalories} setTempValue={setTempCalories} isEditing={isEditingCalories} setIsEditing={setIsEditingCalories} onSave={handleSaveCalories} colorClass="text-primary" unit="kcal" />
          <MacroEditRow label="Step Goal" value={user.dailyStepGoal} tempValue={tempSteps} setTempValue={setTempSteps} isEditing={isEditingSteps} setIsEditing={setIsEditingSteps} onSave={handleSaveSteps} colorClass="text-primary" unit="steps" />
          <MacroEditRow label="Water Goal" value={user.dailyWaterGoal} tempValue={tempWater} setTempValue={setTempWater} isEditing={isEditingWater} setIsEditing={setIsEditingWater} onSave={handleSaveWater} colorClass="text-blue-400" unit="glasses" />
          <MacroEditRow label="Protein Target" value={user.macros.protein} tempValue={tempProtein} setTempValue={setTempProtein} isEditing={isEditingProtein} setIsEditing={setIsEditingProtein} onSave={handleSaveProtein} colorClass="text-emerald-400" />
          <MacroEditRow label="Carbs Target" value={user.macros.carbs} tempValue={tempCarbs} setTempValue={setTempCarbs} isEditing={isEditingCarbs} setIsEditing={setIsEditingCarbs} onSave={handleSaveCarbs} colorClass="text-amber-400" />
