            <div><p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Target Weight</p><p className="text-lg font-black text-primary">{user.targetWeight || 0} <span className="text-xs font-medium text-slate-500 ml-1">kg</span></p></div>
          </div>
