                  </div>

                  <div className="flex items-center space-x-3">
                    <button 
                      onClick={() => toggleReminder(rem.id)}
                      className={`w-12 h-7 rounded-full transition-all duration-300 p-1 flex items-center ${rem.enabled ? 'bg-primary shadow-[0_0_12px_rgba(19,236,55,0.4)]' : 'bg-white/10'}`}
                    >
                      <div className={`w-5 h-5 rounded-full bg-white transition-all shadow-md ${rem.enabled ? 'translate-x-5' : 'translate-x-0'}`}></div>
                    </button>
                    <button 
                      onClick={() => deleteReminder(rem.id)}
                      className="opacity-0 group-hover:opacity-100 p-2 text-slate-600 hover:text-red-500 transition-all"
                    >
                      <span className="material-icons-round text-lg">delete</span>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}

          <div className="pt-4 border-t border-white/5">
            <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest px-1 mb-3">Add Custom Alert</p>
            <div className="grid grid-cols-3 gap-2">
              {[
                { type: 'Meal', icon: 'lunch_dining', color: 'text-orange-400' },
                { type: 'Water', icon: 'water_drop', color: 'text-blue-400' },
                { type: 'Steps', icon: 'directions_walk', color: 'text-primary' },
              ].map((item) => (
                <button 
                  key={item.type}
                  onClick={() => addReminder(item.type as any)}
                  className="bg-white/5 hover:bg-white/10 border border-white/5 py-3 rounded-2xl flex flex-col items-center space-y-1 transition-all active:scale-95"
                >
                  <span className={`material-icons-round text-lg ${item.color}`}>{item.icon}</span>
                  <span className="text-[8px] font-black uppercase text-slate-500 tracking-wider">{item.type}</span>
                </button>
