            </div>
          </div>
        </div>
      </section>

      <section className="space-y-3 pb-10">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Settings & Sync</h2>
        {[
          { id: 'health', icon: 'health_and_safety', label: 'Sync Apple Health / Google Fit', color: 'text-red-400' },
          { id: 'share', icon: 'share', label: 'Invite Friends', color: 'text-orange-400' },
          { id: 'support', icon: 'support_agent', label: 'Customer Support', color: 'text-blue-400' },
        ].map((item, i) => (
          <button key={i} className="w-full flex items-center p-4 bg-white/5 border border-white/5 rounded-[1.8rem] hover:bg-white/10 transition-colors group">
            <span className={`material-icons-round mr-4 ${item.color}`}>{item.icon}</span>
            <span className="text-sm font-bold text-white/80 group-hover:text-white">{item.label}</span>
            <span className="material-icons-round ml-auto text-white/10 group-hover:text-white/30 text-lg">chevron_right</span>
          </button>
        ))}
      </section>
    </div>
  );
};

