import React, { useMemo } from 'react';
import { FoodEntry, UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  entries: FoodEntry[];
  waterGlasses: number;
  setWaterGlasses: (val: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, entries, waterGlasses, setWaterGlasses }) => {
  const consumed = entries.reduce((acc, entry) => acc + entry.calories, 0);
  const isSurplus = consumed > user.dailyCalorieGoal;
  const remaining = Math.max(0, user.dailyCalorieGoal - consumed);
  const surplus = isSurplus ? consumed - user.dailyCalorieGoal : 0;
  const progressPercent = Math.min(100, (consumed / user.dailyCalorieGoal) * 100);

  const totalMacros = useMemo(() => entries.reduce((acc, e) => ({
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
    fi: acc.fi + (e.fiber || 0),
  }), { p: 0, c: 0, f: 0, fi: 0 }), [entries]);

  const stepProgress = Math.min(100, (user.currentSteps / user.dailyStepGoal) * 100);

  // Hero Card Progress Ring
  const mainSize = 240;
  const mainCenter = mainSize / 2;
  const mainRadius = 88;
  const arcDegrees = 260; 
  const mainCircumference = 2 * Math.PI * mainRadius;
  const arcLength = (arcDegrees / 360) * mainCircumference;
  const rotation = 90 + (360 - arcDegrees) / 2;
  const mainOffset = arcLength - (progressPercent / 100) * arcLength;

  const MacroCard = ({ label, current, goal, color, icon }: any) => {
    const macroPercent = Math.min(100, (current / goal) * 100);
    const size = 64;
    const center = size / 2;
    const radius = 24;
    const circ = 2 * Math.PI * radius;
    const mArcDegrees = 240;
    const mArcLength = (mArcDegrees / 360) * circ;
    const mOffset = mArcLength - (macroPercent / 100) * mArcLength;
    const mRotation = 90 + (360 - mArcDegrees) / 2;

    return (
      <div className="glass-card rounded-[2.5rem] p-6 flex flex-col items-center border border-white/5 transition-all hover:bg-white/[0.04] duration-300 animate-in zoom-in-95">
        <div className="relative w-16 h-16 mb-4">
          <svg className="w-full h-full" viewBox={`0 0 ${size} ${size}`} style={{ transform: `rotate(${mRotation}deg)` }}>
            <circle cx={center} cy={center} r={radius} fill="transparent" stroke="rgba(255,255,255,0.02)" strokeWidth="5" strokeDasharray={`${mArcLength} ${circ}`} strokeLinecap="round" />
            <circle cx={center} cy={center} r={radius} fill="transparent" stroke="currentColor" strokeWidth="5" strokeDasharray={`${mArcLength} ${circ}`} strokeDashoffset={mOffset} strokeLinecap="round" className={`${color} transition-all duration-1000`} />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className={`material-icons-round text-sm ${color} opacity-40`}>{icon}</span>
          </div>
        </div>
        <div className="text-center w-full">
          <p className="text-[9px] font-black uppercase tracking-[0.4em] text-white/20 mb-3">{label}</p>
          <div className="flex items-baseline justify-center space-x-1">
            <p className="text-xl font-black text-white">{Math.round(current)}<span className="text-[9px] opacity-20 ml-0.5">g</span></p>
            <p className="text-[10px] font-black text-white/5">/ {goal}g</p>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 pb-24 view-enter">
      <header className="px-1 flex justify-between items-start">
        <div>
          <p className="text-[10px] font-black text-primary uppercase tracking-[0.5em] mb-1 opacity-80">
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' }).toUpperCase()}
          </p>
          <h1 className="text-4xl font-black tracking-tighter text-white">Hey, {user.name.split(' ')[0]}!</h1>
        </div>
        <div className="w-12 h-12 rounded-2xl bg-white/5 border border-white/5 p-1">
          <img src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="Avatar" className="w-full h-full rounded-[14px] object-cover" />
        </div>
      </header>

      {/* Main Calorie Hero - Matched to Screenshot */}
      <section className="glass-card rounded-[3.5rem] p-10 flex flex-col items-center justify-center relative border border-white/5 shadow-2xl overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-primary/[0.03] to-transparent pointer-events-none"></div>

        <div className="relative w-64 h-64 flex items-center justify-center">
          <svg className="w-full h-full" viewBox={`0 0 ${mainSize} ${mainSize}`} style={{ transform: `rotate(${rotation}deg)` }}>
            <circle cx={mainCenter} cy={mainCenter} r={mainRadius} fill="transparent" stroke="rgba(255,255,255,0.02)" strokeWidth="18" strokeDasharray={`${arcLength} ${mainCircumference}`} strokeLinecap="round" />
            <circle cx={mainCenter} cy={mainCenter} r={mainRadius} fill="transparent" stroke="currentColor" strokeWidth="18" strokeDasharray={`${arcLength} ${mainCircumference}`} strokeDashoffset={mainOffset} strokeLinecap="round" className={isSurplus ? "text-red-500" : "text-primary"} style={{ transition: 'stroke-dashoffset 1.5s cubic-bezier(0.2, 0.8, 0.2, 1)', filter: 'drop-shadow(0 0 12px rgba(19,236,55,0.2))' }} />
          </svg>

          <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
            <span className="text-7xl font-black text-white tabular-nums tracking-tighter leading-none">
              {isSurplus ? `+${surplus}` : remaining.toLocaleString()}
            </span>
            <span className="text-[11px] text-white/30 font-black uppercase tracking-[0.6em] mt-5">
              {isSurplus ? 'SURPLUS' : 'KCAL LEFT'}
            </span>
          </div>
        </div>

        {/* Dual Metric Footer */}
        <div className="w-full grid grid-cols-2 mt-10 pt-8 border-t border-white/5">
           <div className="text-center pr-4 border-r border-white/5">
              <p className="text-[9px] font-black text-white/20 uppercase tracking-[0.4em] mb-3">Target</p>
              <div className="flex items-baseline justify-center">
                <span className="text-2xl font-black text-white/60">{user.dailyCalorieGoal.toLocaleString()}</span>
                <span className="text-[9px] font-black text-white/10 ml-2 uppercase tracking-widest">Kcal</span>
              </div>
           </div>
           <div className="text-center pl-4">
              <p className="text-[9px] font-black text-white/20 uppercase tracking-[0.4em] mb-3">Logged</p>
              <div className="flex items-baseline justify-center">
                <span className="text-2xl font-black text-primary">{consumed.toLocaleString()}</span>
                <span className="text-[9px] font-black text-primary/40 ml-2 uppercase tracking-widest">Kcal</span>
              </div>
           </div>
        </div>
      </section>

      {/* Macros Grid - Fixed Alignment */}
      <section className="grid grid-cols-2 gap-5">
        <MacroCard label="Protein" current={totalMacros.p} goal={user.macros.protein} icon="egg" color="text-emerald-400" />
        <MacroCard label="Carbs" current={totalMacros.c} goal={user.macros.carbs} icon="grain" color="text-amber-400" />
      </section>

      {/* Activity Section */}
      <section className="grid grid-cols-2 gap-5">
        <div className="glass-card rounded-[2.5rem] p-7 border border-white/5 flex flex-col justify-between min-h-[160px] hover:bg-white/[0.05] transition-all">
          <div className="flex items-center space-x-3">
             <div className="w-9 h-9 bg-primary/20 rounded-2xl flex items-center justify-center">
               <span className="material-icons-round text-primary text-sm">directions_run</span>
             </div>
             <span className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em]">Steps</span>
          </div>
          <div className="mt-4">
            <div className="flex items-baseline space-x-1.5 mb-4">
              <p className="text-3xl font-black text-white">{user.currentSteps.toLocaleString()}</p>
              <p className="text-[10px] font-black text-white/10 uppercase tracking-widest">/ {user.dailyStepGoal.toLocaleString()}</p>
            </div>
            <div className="w-full h-1.5 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-primary rounded-full transition-all duration-1000" style={{ width: `${stepProgress}%` }}></div>
            </div>
          </div>
        </div>

        <div className="glass-card rounded-[2.5rem] p-7 border border-white/5 flex flex-col justify-between min-h-[160px] hover:bg-white/[0.05] transition-all cursor-pointer" onClick={() => setWaterGlasses(waterGlasses + 1)}>
          <div className="flex items-center space-x-3">
             <div className="w-9 h-9 bg-blue-500/20 rounded-2xl flex items-center justify-center">
               <span className="material-icons-round text-blue-400 text-sm">water_drop</span>
             </div>
             <span className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em]">Water</span>
          </div>
          <div className="mt-4">
            <div className="flex items-baseline space-x-1.5 mb-5">
              <p className="text-3xl font-black text-white">{waterGlasses}</p>
              <p className="text-[10px] font-black text-white/10 uppercase tracking-widest">/ {user.dailyWaterGoal || 10} Cups</p>
            </div>
            <div className="flex gap-1 h-1">
              {Array.from({ length: user.dailyWaterGoal || 10 }).map((_, i) => (
                <div key={i} className={`flex-1 rounded-full transition-all duration-500 ${i < waterGlasses ? 'bg-blue-400' : 'bg-white/5'}`} />
              ))}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef } from 'react';
import { UserProfile, Reminder } from '../types';

interface ProfileProps {
  user: UserProfile;
  onUpdate: (updates: Partial<UserProfile>) => void;
}

const PRESET_AVATARS = [
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Felix',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Aneka',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Tigger',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Spooky',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Buddy',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Cookie',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Milo',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Lilly',
];

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditingCalories, setIsEditingCalories] = useState(false);
  const [isEditingSteps, setIsEditingSteps] = useState(false);
  const [isEditingWater, setIsEditingWater] = useState(false);

  const [isEditingProtein, setIsEditingProtein] = useState(false);
  const [isEditingCarbs, setIsEditingCarbs] = useState(false);
  const [isEditingFats, setIsEditingFats] = useState(false);
  const [isEditingFiber, setIsEditingFiber] = useState(false);

  const [tempCalories, setTempCalories] = useState(user.dailyCalorieGoal);
  const [tempSteps, setTempSteps] = useState(user.dailyStepGoal);
  const [tempWater, setTempWater] = useState(user.dailyWaterGoal || 10);

  const [tempProtein, setTempProtein] = useState(user.macros.protein);
  const [tempCarbs, setTempCarbs] = useState(user.macros.carbs);
  const [tempFats, setTempFats] = useState(user.macros.fats);
  const [tempFiber, setTempFiber] = useState(user.macros.fiber);

  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isIncomplete = !user.dailyCalorieGoal || !user.dailyStepGoal || !user.weight || !user.targetWeight || !user.dailyWaterGoal;

  const goals = [
    { id: 'Cut', icon: 'trending_down', label: 'Lose Weight', desc: 'Calorie deficit' },
    { id: 'Maintain', icon: 'trending_flat', label: 'Stay Fit', desc: 'Equal intake' },
    { id: 'Bulk', icon: 'trending_up', label: 'Build Muscle', desc: 'Calorie surplus' },
  ];

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      if (!file.type.startsWith('image/')) {
        setUploadError('Select a valid image file');
        return;
      }
      if (file.size > MAX_FILE_SIZE) {
        setUploadError('Image too large (>5MB)');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ avatarUrl: reader.result as string });
        setIsModalOpen(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveCalories = () => { onUpdate({ dailyCalorieGoal: tempCalories }); setIsEditingCalories(false); };
  const handleSaveSteps = () => { onUpdate({ dailyStepGoal: tempSteps }); setIsEditingSteps(false); };
  const handleSaveWater = () => { onUpdate({ dailyWaterGoal: tempWater }); setIsEditingWater(false); };
  const handleSaveProtein = () => { onUpdate({ macros: { ...user.macros, protein: tempProtein } }); setIsEditingProtein(false); };
  const handleSaveCarbs = () => { onUpdate({ macros: { ...user.macros, carbs: tempCarbs } }); setIsEditingCarbs(false); };
  const handleSaveFats = () => { onUpdate({ macros: { ...user.macros, fats: tempFats } }); setIsEditingFats(false); };
  const handleSaveFiber = () => { onUpdate({ macros: { ...user.macros, fiber: tempFiber } }); setIsEditingFiber(false); };

  // Reminders
  const toggleReminder = (id: string) => {
    const updated = (user.reminders || []).map(r => r.id === id ? { ...r, enabled: !r.enabled } : r);
    onUpdate({ reminders: updated });
  };
  const addReminder = (type: Reminder['type']) => {
    const newReminder: Reminder = { id: `rem-${Date.now()}`, type, time: '09:00', enabled: true };
    onUpdate({ reminders: [...(user.reminders || []), newReminder] });
  };
  const deleteReminder = (id: string) => {
    const updated = (user.reminders || []).filter(r => r.id !== id);
    onUpdate({ reminders: updated });
  };
  const updateReminderTime = (id: string, time: string) => {
    const updated = (user.reminders || []).map(r => r.id === id ? { ...r, time } : r);
    onUpdate({ reminders: updated });
  };

  const MacroEditRow = ({ label, value, tempValue, setTempValue, isEditing, setIsEditing, onSave, unit = 'g', colorClass = 'text-primary' }: any) => (
    <div className="flex justify-between items-center py-5 border-t border-white/5 first:border-t-0">
      <div className="flex-1">
        <p className="text-[10px] font-black text-white/30 uppercase tracking-widest mb-1">{label}</p>
        {isEditing ? (
          <div className="flex items-center space-x-2">
            <input 
              type="number" value={tempValue} autoFocus
              onChange={(e) => setTempValue(Number(e.target.value))}
              className="bg-white/5 border border-white/10 rounded-lg py-1 px-3 text-lg font-black w-24 focus:outline-none focus:ring-1 focus:ring-primary text-white"
            />
            <button onClick={onSave} className={`w-8 h-8 rounded-lg ${colorClass.replace('text-', 'bg-')} text-black flex items-center justify-center`}><span className="material-icons-round text-sm">check</span></button>
          </div>
        ) : (
          <p className="text-xl font-black text-white">{value || 0} <span className="text-[10px] text-white/20 uppercase ml-1 tracking-widest">{unit}</span></p>
        )}
      </div>
      {!isEditing && (
        <button onClick={() => { setTempValue(value); setIsEditing(true); }} className={`text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl transition-all active:scale-95 ${colorClass.replace('text-', 'bg-')}/10 ${colorClass}`}>
          Adjust
        </button>
      )}
    </div>
  );

  return (
    <div className="space-y-8 pb-20 view-enter">
      <header className="flex flex-col items-center text-center">
        <div className="relative mb-6">
           <div className="w-28 h-28 rounded-[2.2rem] bg-white/5 border-2 border-white/5 p-1 relative overflow-hidden">
              <img src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} alt="Profile" className="w-full h-full rounded-[1.8rem] object-cover" />
              <button onClick={() => setIsModalOpen(true)} className="absolute inset-0 bg-black/40 opacity-0 hover:opacity-100 flex items-center justify-center transition-opacity"><span className="material-icons-round text-white">camera_alt</span></button>
           </div>
        </div>
        <h1 className="text-3xl font-black tracking-tighter text-white">{user.name}</h1>
        <p className="text-[10px] font-black text-primary uppercase tracking-[0.4em] mt-1">Premium Member</p>
      </header>

      {isIncomplete && (
        <div className="bg-primary/10 border border-primary/20 rounded-[2rem] p-5 flex items-center gap-4 mx-1">
          <div className="w-10 h-10 rounded-xl bg-primary flex items-center justify-center text-black shrink-0"><span className="material-icons-round">priority_high</span></div>
          <p className="text-[10px] text-white/60 font-black leading-relaxed uppercase tracking-wider">Please complete your targets below to unlock full AI precision.</p>
        </div>
      )}

      {/* Goal Selection */}
      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 px-1">Fitness Goal</h2>
        <div className="grid grid-cols-1 gap-3">
          {goals.map((g) => (
            <button key={g.id} onClick={() => onUpdate({ goal: g.id as any })} className={`flex items-center p-4 rounded-3xl border transition-all ${user.goal === g.id ? 'bg-primary/10 border-primary' : 'bg-white/5 border-white/5'}`}>
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center mr-4 ${user.goal === g.id ? 'bg-primary text-black' : 'bg-white/5 text-white/20'}`}><span className="material-icons-round">{g.icon}</span></div>
              <div className="text-left"><p className={`text-sm font-black ${user.goal === g.id ? 'text-primary' : 'text-white'}`}>{g.label}</p><p className="text-[9px] font-black text-white/20 uppercase tracking-widest">{g.desc}</p></div>
            </button>
          ))}
        </div>
      </section>

      {/* Targets */}
      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 px-1">Daily Targets</h2>
        <div className="glass-card rounded-[2.5rem] p-8 border border-white/5">
          <MacroEditRow label="Calories" value={user.dailyCalorieGoal} tempValue={tempCalories} setTempValue={setTempCalories} isEditing={isEditingCalories} setIsEditing={setIsEditingCalories} onSave={handleSaveCalories} colorClass="text-primary" unit="kcal" />
          <MacroEditRow label="Step Goal" value={user.dailyStepGoal} tempValue={tempSteps} setTempValue={setTempSteps} isEditing={isEditingSteps} setIsEditing={setIsEditingSteps} onSave={handleSaveSteps} colorClass="text-primary" unit="steps" />
          <MacroEditRow label="Water Goal" value={user.dailyWaterGoal} tempValue={tempWater} setTempValue={setTempWater} isEditing={isEditingWater} setIsEditing={setIsEditingWater} onSave={handleSaveWater} colorClass="text-blue-400" unit="cups" />
          <MacroEditRow label="Protein" value={user.macros.protein} tempValue={tempProtein} setTempValue={setTempProtein} isEditing={isEditingProtein} setIsEditing={setIsEditingProtein} onSave={handleSaveProtein} colorClass="text-emerald-400" />
          <MacroEditRow label="Carbohydrates" value={user.macros.carbs} tempValue={tempCarbs} setTempValue={setTempCarbs} isEditing={isEditingCarbs} setIsEditing={setIsEditingCarbs} onSave={handleSaveCarbs} colorClass="text-amber-400" />
          <MacroEditRow label="Fats" value={user.macros.fats} tempValue={tempFats} setTempValue={setTempFats} isEditing={isEditingFats} setIsEditing={setIsEditingFats} onSave={handleSaveFats} colorClass="text-orange-400" />
        </div>
      </section>

      {/* Reminders - Improved UI Alignment */}
      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 px-1">Smart Alerts</h2>
        <div className="glass-card rounded-[2.5rem] p-6 border border-white/5 space-y-3">
          {(user.reminders || []).map((rem) => (
            <div key={rem.id} className="bg-white/[0.03] border border-white/5 rounded-2xl p-4 flex items-center justify-between group">
              <div className="flex items-center space-x-4">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${rem.type === 'Meal' ? 'bg-orange-500/10 text-orange-400' : rem.type === 'Water' ? 'bg-blue-500/10 text-blue-400' : 'bg-primary/10 text-primary'}`}>
                  <span className="material-icons-round text-xl">{rem.type === 'Meal' ? 'restaurant' : rem.type === 'Water' ? 'water_drop' : 'directions_run'}</span>
                </div>
                <div>
                  <p className="text-[9px] font-black text-white/20 uppercase tracking-widest mb-1">{rem.type}</p>
                  <input type="time" value={rem.time} onChange={(e) => updateReminderTime(rem.id, e.target.value)} className="bg-transparent border-none text-lg font-black text-white p-0 focus:ring-0 cursor-pointer uppercase" />
                </div>
              </div>
              <div className="flex items-center space-x-4">
                <button onClick={() => toggleReminder(rem.id)} className={`w-12 h-7 rounded-full transition-all p-1 flex items-center ${rem.enabled ? 'bg-primary' : 'bg-white/10'}`}>
                  <div className={`w-5 h-5 rounded-full bg-white transition-all ${rem.enabled ? 'translate-x-5' : 'translate-x-0'}`}></div>
                </button>
                <button onClick={() => deleteReminder(rem.id)} className="opacity-0 group-hover:opacity-100 p-2 text-white/20 hover:text-red-500 transition-all"><span className="material-icons-round text-lg">delete</span></button>
              </div>
            </div>
          ))}
          <div className="grid grid-cols-3 gap-2 pt-4 border-t border-white/5">
            {['Meal', 'Water', 'Steps'].map((type) => (
              <button key={type} onClick={() => addReminder(type as any)} className="bg-white/5 hover:bg-white/10 border border-white/5 py-3 rounded-2xl flex flex-col items-center space-y-1 active:scale-95 transition-all">
                <span className="text-[8px] font-black uppercase text-white/40 tracking-widest">{type}</span>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Sync Footer */}
      <section className="space-y-3 pb-10">
        <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 px-1">Settings</h2>
        {['Apple Health Sync', 'Invite Friends', 'Help & Support'].map((label, i) => (
          <button key={i} className="w-full flex items-center p-5 bg-white/5 border border-white/5 rounded-[2rem] hover:bg-white/10 transition-colors group">
            <span className="text-sm font-black text-white/60 group-hover:text-white uppercase tracking-widest">{label}</span>
            <span className="material-icons-round ml-auto text-white/10 text-lg">chevron_right</span>
          </button>
        ))}
      </section>

      {/* Avatar Selection Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="glass-card w-full max-sm rounded-[2.5rem] p-8 border border-white/10 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-black text-white uppercase tracking-widest">Select Profile</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-white/40"><span className="material-icons-round">close</span></button>
            </div>
            <div className="grid grid-cols-4 gap-4">
              {PRESET_AVATARS.map((url, i) => (
                <button key={i} onClick={() => { onUpdate({ avatarUrl: url }); setIsModalOpen(false); }} className={`aspect-square rounded-2xl bg-white/5 border-2 transition-all ${user.avatarUrl === url ? 'border-primary scale-110' : 'border-transparent hover:border-white/10'}`}><img src={url} className="w-full h-full p-2" /></button>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

