          <TargetRow label="Fiber Target" value={user.macros.fiber} unit="grams" onChange={(v: number) => onUpdate({ macros: { ...user.macros, fiber: v } })} />
          <TargetRow label="Step Goal" value={user.dailyStepGoal} unit="steps" onChange={(v: number) => onUpdate({ dailyStepGoal: v })} />
