        <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30 px-1">Smart Alerts</h2>
        <div className="glass-card rounded-[2.5rem] p-6 border border-white/5 space-y-3">
          {(user.reminders || []).map((rem) => (
            <div key={rem.id} className="bg-white/[0.03] border border-white/5 rounded-2xl p-4 flex items-center justify-between group">
              <div className="flex items-center space-x-4">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${rem.type === 'Meal' ? 'bg-orange-500/10 text-orange-400' : rem.type === 'Water' ? 'bg-blue-500/10 text-blue-400' : 'bg-primary/10 text-primary'}`}>
                  <span className="material-icons-round text-xl">{rem.type === 'Meal' ? 'restaurant' : rem.type === 'Water' ? 'water_drop' : 'directions_run'}</span>
                </div>
                <div>
                  <p className="text-[9px] font-black text-white/20 uppercase tracking-widest mb-1">{rem.type}</p>
                  <input type="time" value={rem.time} onChange={(e) => {
                    const updated = (user.reminders || []).map(r => r.id === rem.id ? { ...r, time: e.target.value } : r);
                    onUpdate({ reminders: updated });
                  }} className="bg-transparent border-none text-lg font-black text-white p-0 focus:ring-0 cursor-pointer" />
                </div>
              </div>
              <div className="flex items-center space-x-3">
                <button onClick={() => toggleReminder(rem.id)} className={`w-11 h-6 rounded-full p-1 transition-colors flex items-center ${rem.enabled ? 'bg-primary' : 'bg-white/10'}`}>
                  <div className={`w-4 h-4 rounded-full bg-white transition-transform ${rem.enabled ? 'translate-x-5' : 'translate-x-0'}`} />
                </button>
                <button onClick={() => deleteReminder(rem.id)} className="opacity-0 group-hover:opacity-100 p-2 text-white/20 hover:text-red-500 transition-opacity">
                  <span className="material-icons-round text-lg">delete</span>
                </button>
              </div>
            </div>
          ))}
          <div className="grid grid-cols-3 gap-2 pt-3 border-t border-white/5">
            {['Meal', 'Water', 'Steps'].map(type => (
              <button key={type} onClick={() => addReminder(type as any)} className="bg-white/5 hover:bg-white/10 border border-white/5 py-3 rounded-2xl flex flex-col items-center space-y-1 transition-all active:scale-95">
                <span className="text-[8px] font-black uppercase text-white/30 tracking-widest">{type}</span>
              </button>
            ))}
          </div>
        </div>
      </section>

      <section className="space-y-3 pb-8 px-1">
        <button className="w-full flex items-center p-5 bg-white/5 border border-white/5 rounded-[2rem] hover:bg-white/10 transition-colors group">
          <span className="text-[11px] font-black text-white/50 group-hover:text-white uppercase tracking-[0.2em]">Health Data Sync</span>
          <span className="material-icons-round ml-auto text-white/10 group-hover:text-primary transition-colors">sync</span>
        </button>
        <button onClick={() => signOut(auth)} className="w-full flex items-center justify-center p-5 bg-red-500/5 border border-red-500/10 rounded-[2rem] hover:bg-red-500/10 transition-colors group">
          <span className="text-[11px] font-black text-red-400 uppercase tracking-[0.2em]">Sign Out Account</span>
        </button>
      </section>

      {/* Avatar Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
