import React, { useState, useRef } from 'react';
import { UserProfile, Reminder } from '../types';

interface ProfileProps {
  user: UserProfile;
  onUpdate: (updates: Partial<UserProfile>) => void;
}

const PRESET_AVATARS = [
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Felix',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Aneka',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Tigger',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Spooky',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Buddy',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Cookie',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Milo',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Lilly',
];

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditingCalories, setIsEditingCalories] = useState(false);
  const [isEditingSteps, setIsEditingSteps] = useState(false);
  const [tempCalories, setTempCalories] = useState(user.dailyCalorieGoal);
  const [tempSteps, setTempSteps] = useState(user.dailyStepGoal);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isIncomplete = !user.dailyCalorieGoal || !user.dailyStepGoal || !user.weight || !user.targetWeight;

  const goals = [
    { id: 'Cut', icon: 'trending_down', label: 'Lose Weight', desc: 'Calorie deficit' },
    { id: 'Maintain', icon: 'trending_flat', label: 'Stay Fit', desc: 'Equal intake' },
    { id: 'Bulk', icon: 'trending_up', label: 'Build Muscle', desc: 'Calorie surplus' },
  ];

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      if (!file.type.startsWith('image/')) {
        setUploadError('Please select a valid image file (PNG, JPG, etc.)');
        return;
      }
      if (file.size > MAX_FILE_SIZE) {
        setUploadError('Image is too large. Please select a file under 5MB.');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ avatarUrl: reader.result as string });
        setIsModalOpen(false);
      };
      reader.onerror = () => {
        setUploadError('Error reading file. Please try again.');
      };
      reader.readAsDataURL(file);
    }
  };

  const selectPreset = (url: string) => {
    setUploadError(null);
    onUpdate({ avatarUrl: url });
    setIsModalOpen(false);
  };

  const generateNewDiceBear = () => {
    setUploadError(null);
    const randomSeed = Math.random().toString(36).substring(7);
    onUpdate({ avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=${randomSeed}` });
    setIsModalOpen(false);
  };

  const handleSaveCalories = () => {
    onUpdate({ dailyCalorieGoal: tempCalories });
    setIsEditingCalories(false);
  };

  const handleSaveSteps = () => {
    onUpdate({ dailyStepGoal: tempSteps });
    setIsEditingSteps(false);
  };

  const toggleReminder = (id: string) => {
    const updated = (user.reminders || []).map(r => r.id === id ? { ...r, enabled: !r.enabled } : r);
    onUpdate({ reminders: updated });
  };

  const addReminder = (type: Reminder['type']) => {
    const newRem: Reminder = { id: `rem-${Date.now()}`, type, time: '09:00', enabled: true };
    onUpdate({ reminders: [...(user.reminders || []), newRem] });
  };

  const deleteReminder = (id: string) => {
    onUpdate({ reminders: (user.reminders || []).filter(r => r.id !== id) });
  };

  const updateReminderTime = (id: string, time: string) => {
    const updated = (user.reminders || []).map(r => r.id === id ? { ...r, time } : r);
    onUpdate({ reminders: updated });
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col items-center text-center">
        <div className="relative group mb-4">
           <div className="absolute -inset-1 bg-gradient-to-tr from-primary to-primary/20 rounded-[2rem] blur opacity-25 group-hover:opacity-50 transition duration-500"></div>
           <div className="relative w-28 h-28 rounded-[2rem] bg-background-dark border-2 border-white/5 p-1 shadow-2xl overflow-hidden">
              <img 
                src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} 
                alt="Profile" 
                className="w-full h-full rounded-[1.8rem] bg-surface-dark object-cover" 
              />
              <button 
                onClick={() => setIsModalOpen(true)}
                className="absolute -bottom-2 -right-2 w-10 h-10 bg-primary rounded-2xl flex items-center justify-center text-black shadow-lg border-4 border-background-dark active:scale-90 transition-transform"
              >
                <span className="material-icons-round text-xl">camera_alt</span>
              </button>
           </div>
        </div>
        <h1 className="text-2xl font-black tracking-tight">{user.name}</h1>
        <p className="text-sm text-slate-500 font-medium">NutriVision Free Plan</p>
      </header>

      {/* Completion Prompt */}
      {isIncomplete && (
        <div className="bg-primary/10 border border-primary/20 rounded-[2rem] p-5 flex items-center gap-4 animate-in fade-in slide-in-from-top-4 duration-700 mx-1">
          <div className="w-12 h-12 rounded-2xl bg-primary/20 flex items-center justify-center text-primary shrink-0">
            <span className="material-icons-round text-2xl">priority_high</span>
          </div>
          <div className="flex-1">
            <p className="text-[11px] font-black text-primary uppercase tracking-[0.15em]">Setup Incomplete</p>
            <p className="text-[10px] text-white/60 font-bold leading-relaxed mt-1">
              Add your targets and weight below. Complete data allows the AI to give you 100% accurate macro scores.
            </p>
          </div>
        </div>
      )}

      {/* Avatar Customization Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass-card w-full max-sm rounded-[2.5rem] p-6 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden relative">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-black tracking-tight text-white">Choose Avatar</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-white/40 hover:text-white transition-colors">
                <span className="material-icons-round text-lg">close</span>
              </button>
            </div>

            <div className="space-y-6">
              {uploadError && (
                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 animate-in shake duration-300">
                  <span className="material-icons-round text-red-400 text-sm">error_outline</span>
                  <p className="text-[10px] font-bold text-red-400 uppercase tracking-wider">{uploadError}</p>
                </div>
              )}

              <button 
                onClick={() => fileInputRef.current?.click()}
                className={`w-full flex items-center p-4 bg-primary/10 border border-primary/20 rounded-2xl group active:scale-[0.98] transition-all`}
              >
                <div className="w-10 h-10 rounded-xl bg-primary text-black flex items-center justify-center mr-4">
                  <span className="material-icons-round">upload</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-primary uppercase tracking-wider">Upload Photo</p>
                  <p className="text-[10px] text-slate-500 font-bold">Select from gallery (Max 5MB)</p>
                </div>
                <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
              </button>

              <div className="space-y-3">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Presets</p>
                <div className="grid grid-cols-4 gap-3">
                  {PRESET_AVATARS.map((url, i) => (
                    <button key={i} onClick={() => selectPreset(url)} className={`aspect-square rounded-xl bg-white/5 border-2 transition-all active:scale-90 ${user.avatarUrl === url ? 'border-primary' : 'border-transparent hover:border-white/10'}`}>
                      <img src={url} alt={`Preset ${i}`} className="w-full h-full p-1" />
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Active Goal</h2>
        <div className="grid grid-cols-1 gap-3">
          {goals.map((g) => (
            <button key={g.id} onClick={() => onUpdate({ goal: g.id as any })} className={`flex items-center p-4 rounded-3xl border transition-all ${user.goal === g.id ? 'bg-primary/10 border-primary shadow-[0_0_20px_rgba(19,236,55,0.1)]' : 'bg-white/5 border-white/5 hover:border-white/10'}`}>
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 ${user.goal === g.id ? 'bg-primary text-black' : 'bg-white/5 text-slate-500'}`}><span className="material-icons-round text-2xl">{g.icon}</span></div>
              <div className="text-left flex-1">
                <p className={`font-black tracking-tight ${user.goal === g.id ? 'text-primary' : 'text-white'}`}>{g.label}</p>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{g.desc}</p>
              </div>
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Daily Targets</h2>
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 space-y-6">
          <div className="flex justify-between items-start pb-6 border-b border-white/5">
            <div className="cursor-pointer group" onClick={() => { if (!isEditingCalories) { setTempCalories(user.dailyCalorieGoal); setIsEditingCalories(true); } }}>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-primary transition-colors">Calories</p>
              {isEditingCalories ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input type="number" value={tempCalories} autoFocus onChange={(e) => setTempCalories(Number(e.target.value))} className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white" />
                  <button onClick={handleSaveCalories} className="w-8 h-8 rounded-lg bg-primary text-black flex items-center justify-center active:scale-90"><span className="material-icons-round text-sm">check</span></button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-primary transition-colors">{user.dailyCalorieGoal || 0} <span className="text-xs font-medium text-slate-500 ml-1">kcal</span></p>
              )}
            </div>
          </div>

          <div className="flex justify-between items-start pb-6 border-b border-white/5">
            <div className="cursor-pointer group" onClick={() => { if (!isEditingSteps) { setTempSteps(user.dailyStepGoal); setIsEditingSteps(true); } }}>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-primary transition-colors">Step Goal</p>
              {isEditingSteps ? (
                <div className="flex items-center space-x-2" onClick={(e) => e.stopPropagation()}>
                  <input type="number" value={tempSteps} autoFocus onChange={(e) => setTempSteps(Number(e.target.value))} className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white" />
                  <button onClick={handleSaveSteps} className="w-8 h-8 rounded-lg bg-primary text-black flex items-center justify-center active:scale-90"><span className="material-icons-round text-sm">check</span></button>
                </div>
              ) : (
                <p className="text-xl font-black group-hover:text-primary transition-colors">{user.dailyStepGoal || 0} <span className="text-xs font-medium text-slate-500 ml-1">steps</span></p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Current Weight</p>
              <p className="text-lg font-black">{user.weight || 0} <span className="text-xs font-medium text-slate-500 ml-1">kg</span></p>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Target Weight</p>
              <p className="text-lg font-black text-primary">{user.targetWeight || 0} <span className="text-xs font-medium text-slate-500 ml-1">kg</span></p>
            </div>
          </div>
        </div>
      </section>

      {/* NEW: Reminders & Notifications Section */}
      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Reminders & Notifications</h2>
        <div className="glass-card rounded-[2.5rem] p-6 border border-white/5 space-y-4">
          {(user.reminders || []).length === 0 ? (
